
const MODULES={"Command": ["Executive overview", "Dubai hub control", "Global network", "Operational KPIs", "Shift handover", "Alert center"], "Flight & Airport": ["Live flight board", "Flight detail", "Aircraft rotations", "Fleet registry", "Airport capacity", "Gates & stands", "Ground turnaround", "Airspace & NOTAM", "Weather intelligence", "Trajectory analysis"], "Disruption & Recovery": ["Incident command", "Disruption prediction", "Impact assessment", "Recovery optimizer", "Scenario comparison", "Human approvals", "Decision history"], "Engineering & Safety": ["Engine health", "Predictive maintenance", "Maintenance planning", "Safety occurrences", "Hazard register", "Risk assessment", "Reliability analytics"], "People & Commercial": ["Crew operations", "Passenger connections", "Customer experience", "Baggage exceptions", "Cargo logistics", "Fuel & emissions", "Commercial intelligence", "Network planning"], "AI Intelligence": ["AI agent command", "Ten specialist agents", "Document intelligence", "Evidence & RAG", "Prediction models", "Model evaluation", "Prompt & tool policies", "AI evaluation lab"], "Data Platform": ["Data operations catalog", "Ingestion pipelines", "Streaming events", "Lakehouse explorer", "Data quality", "Lineage explorer", "Data access requests", "Dataset registry"], "Enterprise": ["Identity & access", "Roles & permissions", "Security center", "Audit trail", "API gateway", "Cloud infrastructure", "Observability", "Disaster recovery", "Release management", "System settings"]}, DOMAINS=["Flight schedules", "Flight movements", "Aircraft fleet", "Aircraft rotations", "Airport capacity", "Ground handling", "Crew planning", "Weather observations", "Airspace restrictions", "Aircraft trajectories", "Engine health", "Maintenance", "Safety occurrences", "Operational risk", "Passenger connections", "Passenger service", "Baggage", "Cargo", "Fuel", "Emissions", "Commercial performance", "Network planning", "Disruption cases", "Recovery scenarios", "AI predictions", "AI agent execution", "Knowledge and documents", "Data governance", "Security and audit", "Platform operations"], AGENTS=["Operations coordinator", "Flight disruption analyst", "Weather intelligence", "Fleet engineering", "Safety evidence analyst", "Passenger impact", "Crew constraint analyst", "Cargo operations", "Recovery optimization", "Governance verifier"];
const $=id=>document.getElementById(id);const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const now=()=>new Date().toISOString();const stamp=()=>new Date().toLocaleString('en-GB',{timeZone:'UTC',hour12:false})+' UTC';
const SEED={flights:[{id:'AIN-201',route:'DXB → LHR',aircraft:'A380',gate:'A14',eta:'12:45',delay:18,risk:'Medium',status:'Boarding'},{id:'AIN-315',route:'DXB → SYD',aircraft:'B777',gate:'B22',eta:'13:20',delay:0,risk:'Low',status:'Scheduled'},{id:'AIN-412',route:'DXB → SIN',aircraft:'A380',gate:'A07',eta:'14:05',delay:42,risk:'High',status:'Delayed'},{id:'AIN-506',route:'DXB → JFK',aircraft:'B777',gate:'C11',eta:'15:30',delay:24,risk:'Medium',status:'Scheduled'},{id:'AIN-618',route:'DXB → BOM',aircraft:'B777',gate:'B09',eta:'16:00',delay:0,risk:'Low',status:'Boarding'},{id:'AIN-728',route:'DXB → CDG',aircraft:'A380',gate:'A19',eta:'17:10',delay:65,risk:'High',status:'Delayed'}],incidents:[{id:'SIM-101',title:'Weather capacity restriction',severity:'High',owner:'Network Operations',status:'Investigating',notes:'Synthetic scenario - no real airport status.'},{id:'SIM-102',title:'Aircraft rotation conflict',severity:'Medium',owner:'Fleet Control',status:'Open',notes:'Synthetic scenario - planning exercise.'}],approvals:[{id:'APR-001',title:'Recovery option B: protect connections',status:'Pending',owner:'Operations Director',rationale:''},{id:'APR-002',title:'Crew duty feasibility review',status:'Pending',owner:'Crew Manager',rationale:''}],audit:[{time:now(),event:'demo.initialized',detail:'Synthetic data loaded in browser'}]};
let state=structuredClone(SEED),page='Executive overview',role='Operations Director',search='',riskFilter='All',selectedScenario='B',theme='dark';const navNames=Object.values(MODULES).flat();
function audit(event,detail){state.audit.unshift({time:now(),event,detail});}function notify(msg){$('toastRoot').innerHTML='<div class="toast" role="status">'+escapeHtml(msg)+'</div>';setTimeout(()=>{$('toastRoot').innerHTML=''},3600)}function pill(t){const s=String(t).toLowerCase();return `<span class="pill ${/high|critical|rejected|failed|delayed/.test(s)?'bad':/pending|medium|investigating|open/.test(s)?'warn':/low|approved|healthy|complete|boarding/.test(s)?'good':'info'}">${escapeHtml(t)}</span>`}function button(text,action,extra=''){return `<button class="btn sm" data-action="${escapeHtml(action)}" ${extra}>${escapeHtml(text)}</button>`}function head(title,desc,actions=''){return `<div class="title-row"><div><div class="eyebrow">Aviation Intelligence Nexus · independent demo</div><h2>${escapeHtml(title)}</h2><div class="muted">${escapeHtml(desc)}</div></div><div class="toolbar">${actions}</div></div>`}function kpi(label,value,foot){return `<div class="card"><div class="kpi-label">${escapeHtml(label)}</div><div class="kpi-num">${escapeHtml(value)}</div><div class="kpi-foot">${escapeHtml(foot)}</div></div>`}function gridRows(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${escapeHtml(x)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty">No matching records</td></tr>`}</tbody></table></div>`}
const MAP=`<svg class="map" viewBox="0 0 850 300" role="img" aria-label="Illustrative route network from Dubai to London, Paris, Mumbai, Singapore, Sydney and New York"><defs><radialGradient id="g"><stop stop-color="#2a5a67"/><stop offset="1" stop-color="#081724"/></radialGradient></defs><rect width="850" height="300" rx="12" fill="url(#g)"/><g opacity=".12" stroke="#9ac5cf"><path d="M0 60H850M0 120H850M0 180H850M0 240H850M140 0V300M280 0V300M420 0V300M560 0V300M700 0V300"/></g><path d="M470 150Q380 40 250 85M470 150Q340 15 170 110M470 150Q550 75 600 110M470 150Q650 60 745 190M470 150Q510 165 565 200M470 150Q275 160 85 210"/><circle class="hub" cx="470" cy="150" r="7"/><text x="480" y="145">DXB · HUB</text><circle cx="250" cy="85" r="4"/><text x="225" y="70">LHR</text><circle cx="170" cy="110" r="4"/><text x="145" y="95">CDG</text><circle cx="600" cy="110" r="4"/><text x="606" y="104">SIN</text><circle cx="745" cy="190" r="4"/><text x="751" y="185">SYD</text><circle cx="565" cy="200" r="4"/><text x="573" y="216">BOM</text><circle cx="85" cy="210" r="4"/><text x="53" y="227">JFK</text><text x="18" y="24" opacity=".7">SIMULATED NETWORK · NOT LIVE FLIGHT TRACKING</text></svg>`;
function photoStrip(){return `<div class="photo-strip"><div class="photo" style="background-image:url('https://images.unsplash.com/photo-1436491865332-7a61a109cc05?auto=format&fit=crop&w=850&q=80')"><span>Global flight intelligence</span></div><div class="photo" style="background-image:url('https://images.unsplash.com/photo-1474302770737-173ee21bab63?auto=format&fit=crop&w=850&q=80')"><span>Aircraft operations</span></div><div class="photo" style="background-image:url('https://images.unsplash.com/photo-1488085061387-422e29b40080?auto=format&fit=crop&w=850&q=80')"><span>Passenger experience</span></div></div>`}
function flightTable(){let data=state.flights.filter(f=>(riskFilter==='All'||f.risk===riskFilter)&&JSON.stringify(f).toLowerCase().includes(search.toLowerCase()));return gridRows(['Flight','Route','Aircraft','Gate','ETD (UTC)','Delay','Risk','Status','Details'],data.map(f=>[escapeHtml(f.id),escapeHtml(f.route),escapeHtml(f.aircraft),escapeHtml(f.gate),escapeHtml(f.eta),escapeHtml(f.delay)+' min',pill(f.risk),pill(f.status),button('Inspect','flight:'+f.id)]))}
function flightControls(){return `<div class="toolbar"><input class="control" id="filterText" value="${escapeHtml(search)}" placeholder="Search flights, aircraft, routes" aria-label="Filter flights"><select class="control" id="riskFilter" aria-label="Filter by risk">${['All','Low','Medium','High'].map(x=>`<option ${riskFilter===x?'selected':''}>${x}</option>`).join('')}</select>${button('Export flights CSV','exportFlights')}${button('Create incident','newIncident')}</div>`}
function overview(){return `<div class="hero"><div><div class="eyebrow">🇦🇪 Dubai hub · Aviation intelligence · Signature experience</div><h1>See the network.<br><span style="color:var(--gold)">Anticipate what comes next.</span></h1><p>Decision intelligence across operations, predictive AI, recovery optimization, safety and enterprise governance.</p><div class="toolbar">${button('Open flight board','go:Live flight board')}${button('Review approvals','go:Human approvals')}${button('Explore AI agents','go:AI agent command')}</div></div><div class="hero-right"><span class="hero-badge">● SYNTHETIC DEMO DATA</span><p class="small" style="color:#d2dfeb">${stamp()}</p></div></div><div class="grid kpis">${kpi('Monitored flights',state.flights.length,'Illustrative flight records')}${kpi('Active disruption cases',state.incidents.filter(x=>x.status!=='Resolved').length,'Browser-local simulation')}${kpi('Approval queue',state.approvals.filter(x=>x.status==='Pending').length,'Human decision checkpoint')}${kpi('Operational domains',DOMAINS.length,'Catalogued, not integrated')}</div>${photoStrip()}<div class="split"><div class="card"><h3>Global network · Dubai hub</h3>${MAP}<div class="footnote">Route geometry is illustrative and does not represent real-time aircraft positions.</div></div><div class="card"><h3>Operational intelligence queue</h3><div class="list">${state.incidents.map(x=>`<div class="listrow"><div><strong>${escapeHtml(x.title)}</strong><small>${escapeHtml(x.id)} · ${escapeHtml(x.owner)}</small></div>${pill(x.severity)}</div>`).join('')}<div class="listrow"><div><strong>10 governed specialist agent roles</strong><small>Tool contracts, approvals and execution traces planned</small></div>${pill('Design')}</div></div></div></div>${head('Flight operations','Illustrative schedules and risk signals',button('Open flight board','go:Live flight board'))}${flightTable()}`}
function flights(){return head(page,'Search, filter, inspect and export synthetic flight operations',button('Create incident','newIncident'))+flightControls()+flightTable()+`<div class="banner">Real airline operational integration requires an authorized source, provenance, timestamps, licensing, and operational validation.</div>`}
function incidents(){return head(page,'Create, assign, investigate and resolve synthetic disruption cases',button('Create incident','newIncident'))+gridRows(['Case','Incident','Severity','Owner','Status','Action'],state.incidents.map(x=>[escapeHtml(x.id),escapeHtml(x.title),pill(x.severity),escapeHtml(x.owner),pill(x.status),button('Manage','incident:'+x.id)]))+`<div class="card" style="margin-top:18px"><h3>Operational case lifecycle</h3><div class="chip-row">${['Detected','Triaged','Investigating','Recovery proposed','Human approved','Resolved','Audited'].map(x=>`<span class="tag">${x}</span>`).join('')}</div><p class="footnote">A production implementation must enforce role permissions, valid state transitions, idempotency, audit integrity and approval separation.</p></div>`}
const scenarios=[{id:'A',name:'Minimum schedule deviation',delay:92,connections:34,cost:125,feasible:true},{id:'B',name:'Protect critical connections',delay:108,connections:12,cost:148,feasible:true},{id:'C',name:'Aggressive recovery',delay:76,connections:49,cost:166,feasible:false}];
function recovery(){return head(page,'Compare synthetic network recovery alternatives; require independent feasibility checks',button('Review approvals','go:Human approvals'))+`<div class="grid agent-grid">${scenarios.map(s=>`<div class="card"><div class="eyebrow">Scenario ${s.id}</div><h3>${s.name}</h3><p>${pill(s.feasible?'Illustrative feasible':'Illustrative infeasible')}</p><div class="list"><div class="listrow"><span>Delay minutes</span><strong>${s.delay}</strong></div><div class="listrow"><span>At-risk connections</span><strong>${s.connections}</strong></div><div class="listrow"><span>Relative cost units</span><strong>${s.cost}</strong></div></div><div class="toolbar">${button('Select scenario','scenario:'+s.id)}${button('Request review','review:'+s.id,s.feasible?'':'disabled title="Infeasible scenario"')}</div></div>`).join('')}</div><div class="banner">These scenario outputs are hand-authored examples, not OR-Tools solutions. Real optimization must model and independently verify constraints before any approval.</div>`}
function approvals(){return head(page,'Human-in-the-loop decision controls with rationale capture',button('Export audit','exportAudit'))+gridRows(['Request','Proposal','Owner','Status','Decision'],state.approvals.map(x=>[escapeHtml(x.id),escapeHtml(x.title),escapeHtml(x.owner),pill(x.status),x.status==='Pending'?button('Review','approval:'+x.id):escapeHtml(x.rationale||'Decision recorded')]))+`<div class="banner">Browser-local approval demonstrations are not secure or immutable. Production approval must be enforced server-side with identity, policy checks, transactions and tamper-evident audit.</div>`}
function agents(){return head(page,'Ten specialized aviation AI agent roles with governed tools and human oversight')+`<div class="grid agent-grid">${AGENTS.map((x,i)=>`<div class="card"><div class="agent-icon">${['🧭','✈','🌦','⚙','🛡','👥','🧑‍✈️','📦','📐','🔐'][i]}</div><div class="eyebrow">Agent ${String(i+1).padStart(2,'0')}</div><h3>${escapeHtml(x)}</h3><p class="muted">Typed tool permissions · Evidence provenance · Policy checkpoint · Execution trace</p>${button('View contract','agent:'+i)}</div>`).join('')}</div><div class="banner">No LLM calls or agent executions occur in this standalone HTML. The cards are role and interaction specifications.</div>`}
function domains(){return head(page,'Thirty airline data domains with data governance requirements',button('Export catalog','exportDomains'))+`<div class="grid domain-grid">${DOMAINS.map((x,i)=>`<div class="card"><div class="eyebrow">Domain ${String(i+1).padStart(2,'0')}</div><h3>${escapeHtml(x)}</h3><div class="chip-row"><span class="tag">Schema</span><span class="tag">Quality</span><span class="tag">Lineage</span><span class="tag">Access</span><span class="tag">Retention</span></div><p class="muted">Ingestion → Validation → Storage → Query → Governance</p>${button('View requirements','domain:'+i)}</div>`).join('')}</div>`}
const architecture=[['Identity and policy','OIDC / SSO / MFA · RBAC / ABAC · tenant isolation · audit'],['Experience','React / TypeScript · design system · accessibility · browser tests'],['API and workflow','FastAPI · OpenAPI · PostgreSQL · transactional outbox · approvals'],['Operational intelligence','Flight cases · maintenance · crew · safety · passenger · cargo'],['AI and optimization','Predictive ML · MLflow · RAG · LangGraph · OR-Tools · verification'],['Data platform','Kafka · Airflow · Spark · Iceberg · S3 · catalog · quality · lineage'],['Cloud operations','Terraform · Kubernetes · CI/CD · telemetry · backups · DR']];
function enterprise(){return head(page,'Target enterprise architecture and release controls')+`<div class="split equal"><div class="card"><h3>Production service layers</h3><div class="architecture">${architecture.map(x=>`<div class="arch-layer"><strong>${x[0]}</strong><p class="muted small" style="margin:4px 0 0">${x[1]}</p></div>`).join('')}</div></div><div class="card"><h3>Release qualification gates</h3>${['Requirements and ADR approval','Working backend and persistent database','Verified authorization and tenant isolation','Time-safe data and model evaluation','Grounded RAG and agent tool restrictions','Independently checked optimization','Accessible responsive browser experience','Load, failover and backup restoration tests','Monitoring, alerting and incident runbooks','Deployment rollback and documented release evidence'].map((x,i)=>`<div class="step"><div class="step-num">${i+1}</div><div><strong>${x}</strong><div class="muted small">Required evidence · Not yet verified</div></div></div>`).join('')}</div></div>`}
function auditPage(){return head(page,'Browser-local audit demonstration; not immutable or server-verified',button('Export audit CSV','exportAudit'))+gridRows(['Timestamp','Event','Detail'],state.audit.map(x=>[escapeHtml(x.time),escapeHtml(x.event),escapeHtml(x.detail)]))}
function generic(){const domain=DOMAINS.find(x=>page.toLowerCase().includes(x.toLowerCase().split(' ')[0]));return head(page,'Enterprise workflow specification · synthetic demonstration')+`<div class="grid kpis">${kpi('Data readiness','Design','Source integration required')}${kpi('Workflow state','Planned','Backend implementation required')}${kpi('Governance','Required','Authorization + audit')}${kpi('Qualification','Pending','Automated tests needed')}</div><div class="split"><div class="card"><h3>Required functional capabilities</h3>${['Search, filter and inspect records','Create and update authorized workflow items','Validate source data and schema contracts','Track timestamps, lineage and data quality','Escalate incidents and assign ownership','Record decisions, rationale and approvals','Export authorized reports and audit history','Handle errors, retries and empty states'].map((x,i)=>`<div class="step"><div class="step-num">${i+1}</div><span>${x}</span></div>`).join('')}</div><div class="card"><h3>Production implementation contract</h3><p class="muted">This workspace is a UI specification. Implement APIs, persistent data models, identity policies, telemetry and automated tests before representing it as live functionality.</p><div class="chip-row"><span class="tag">API contract</span><span class="tag">Database schema</span><span class="tag">RBAC</span><span class="tag">Event model</span><span class="tag">Monitoring</span><span class="tag">E2E tests</span></div><div style="margin-top:18px">${button('Explore data catalog','go:Data operations catalog')}${button('View architecture','go:Cloud infrastructure')}</div></div></div>`}


const AIN_CATEGORY_MEDIA = [
  [/passenger|customer|journey|service|experience|connection|baggage/i,['Passenger journeys','photo-1488085061387-422e29b40080']],
  [/maintenance|engine|aircraft|fleet|component|reliability/i,['Fleet and engineering','photo-1436491865332-7a61a109cc05']],
  [/weather|airspace|notam|forecast|trajectory/i,['Weather and flight planning','photo-1500835556837-99ac94a94552']],
  [/cargo|logistics|ground|airport|gate|turnaround/i,['Airport and ground operations','photo-1474302770737-173ee21bab63']],
  [/agent|model|predict|rag|knowledge|ai |mlops/i,['AI decision intelligence','photo-1464037866556-6812c9d1c72e']],
  [/security|audit|governance|identity|permission|cloud|release|data|platform/i,['Governed enterprise operations','photo-1500835556837-99ac94a94552']],
  [/crew|safety|risk|incident|recovery|disruption|approval/i,['Operational readiness','photo-1474302770737-173ee21bab63']],
  [/dubai|network|executive|flight/i,['Dubai aviation gateway','photo-1436491865332-7a61a109cc05']]
];
function workspaceMedia(){return (AIN_CATEGORY_MEDIA.find(x=>x[0].test(page))||AIN_CATEGORY_MEDIA[7])[1]}
function exportWorkspaceBrief(){
  const payload={project:'Aviation Intelligence Nexus',status:'INDEPENDENT SYNTHETIC FRONTEND DEMO',workspace:page,exported_at:new Date().toISOString(),data_source:'browser demonstration',production_required:['identity','backend','database','airline integration','security qualification','automated tests']};
  const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='AIN_'+page.toLowerCase().replace(/[^a-z0-9]+/g,'_')+'_brief.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);
}
function addWorkspaceQuickTools(){const content=document.getElementById('content');const bar=document.createElement('div');bar.className='quick-tools';bar.innerHTML='<span class="tag">🇦🇪 UAE-inspired design</span><span class="tag">Independent portfolio prototype</span><button class="btn sm" id="ainWorkspaceExport">Export workspace brief</button><button class="btn sm" id="ainWorkspacePrint">Print workspace</button><span class="tag">Data: synthetic</span>';const media=content.querySelector('.workspace-media');if(media)media.after(bar);document.getElementById('ainWorkspaceExport').onclick=exportWorkspaceBrief;document.getElementById('ainWorkspacePrint').onclick=()=>window.print()}

const AIN_WORKSPACE_MEDIA = [["Dubai aviation gateway", "photo-1436491865332-7a61a109cc05"], ["International flight operations", "photo-1474302770737-173ee21bab63"], ["Passenger journeys", "photo-1488085061387-422e29b40080"], ["Air travel experience", "photo-1464037866556-6812c9d1c72e"], ["Aircraft in flight", "photo-1500835556837-99ac94a94552"], ["Airport operations", "photo-1436491865332-7a61a109cc05"], ["Global aviation network", "photo-1474302770737-173ee21bab63"], ["UAE travel and hospitality", "photo-1488085061387-422e29b40080"]];
const AIN_UI_SETTINGS = {density:localStorage.getItem('ain-density')||'comfortable',images:localStorage.getItem('ain-images')||'on'};
function decorateWorkspace(){
  const target=document.getElementById('content'); if(!target)return;
  const index=Math.max(0,navNames.indexOf(page));
  const image=workspaceMedia();
  const url='https://images.unsplash.com/'+image[1]+'?auto=format&fit=crop&w=1600&q=82';
  const photo=AIN_UI_SETTINGS.images==='on'?`style="--workspace-photo:url('${url}')"`:'';
  const wrap=document.createElement('div');
  wrap.innerHTML=`<div class="workspace-controls"><span class="badge-demo">● INDEPENDENT SIMULATION · NOT LIVE AIRLINE DATA</span><div class="toolbar"><label for="ainDensity">Layout</label><select id="ainDensity" class="control" aria-label="Workspace density"><option value="comfortable" ${AIN_UI_SETTINGS.density==='comfortable'?'selected':''}>Comfortable</option><option value="compact" ${AIN_UI_SETTINGS.density==='compact'?'selected':''}>Compact</option></select><label for="ainPhotos">Photography</label><select id="ainPhotos" class="control" aria-label="Workspace photography"><option value="on" ${AIN_UI_SETTINGS.images==='on'?'selected':''}>On</option><option value="off" ${AIN_UI_SETTINGS.images==='off'?'selected':''}>Off</option></select></div></div><section class="workspace-media" ${photo} aria-label="${escapeHtml(page)} aviation photo banner"><div class="workspace-media-body"><div class="media-kicker">🇦🇪 UAE · Dubai aviation intelligence · Crimson signature edition</div><h2>${escapeHtml(page)}</h2><p>${escapeHtml(image[0])} · Explore aviation intelligence, governed decisions and operational visibility.</p><div class="media-source">Aviation-inspired editorial imagery. Independent project; not affiliated with or endorsed by Emirates Airlines.</div></div></section><div class="page-note">Workspace displays illustrative data unless a verified integration is explicitly indicated. Production functionality requires server-side implementation and tests.</div>`;
  target.prepend(wrap);
  document.body.classList.toggle('compact-view',AIN_UI_SETTINGS.density==='compact');
  document.getElementById('ainDensity').addEventListener('change',e=>{AIN_UI_SETTINGS.density=e.target.value;localStorage.setItem('ain-density',e.target.value);document.body.classList.toggle('compact-view',e.target.value==='compact')});
  document.getElementById('ainPhotos').addEventListener('change',e=>{AIN_UI_SETTINGS.images=e.target.value;localStorage.setItem('ain-images',e.target.value);decoratePhoto()});addWorkspaceQuickTools();
}
function decoratePhoto(){let banner=document.querySelector('.workspace-media');if(!banner)return;let i=Math.max(0,navNames.indexOf(page));let img=workspaceMedia()[1];banner.style.setProperty('--workspace-photo',AIN_UI_SETTINGS.images==='on'?`url('https://images.unsplash.com/${img}?auto=format&fit=crop&w=1600&q=82')`:'none')}

function render(){document.title='AIN | '+page;$('breadcrumb').textContent=page;$('nav').innerHTML=Object.entries(MODULES).map(([cat,names])=>`<div class="nav-section">${escapeHtml(cat)} <span class="nav-count">${names.length}</span></div>`+names.map(x=>`<button class="nav-item ${x===page?'active':''}" data-page="${escapeHtml(x)}"><span>${escapeHtml(x)}</span>${x===page?'●':''}</button>`).join('')).join('');let lower=page.toLowerCase();$('content').innerHTML=page==='Executive overview'?overview():/flight board|flight detail|aircraft rotations|fleet registry|global network|dubai hub control/.test(lower)?flights():/incident command|disruption center|impact assessment|disruption prediction/.test(lower)?incidents():/recovery optimizer|scenario comparison/.test(lower)?recovery():/human approvals|decision history/.test(lower)?approvals():/ai agent command|ten specialist agents/.test(lower)?agents():/data operations catalog|dataset registry/.test(lower)?domains():/audit trail/.test(lower)?auditPage():/cloud infrastructure|release management|security center|disaster recovery|identity & access|roles & permissions|system settings/.test(lower)?enterprise():generic();decorateWorkspace();}
function go(p){if(!navNames.includes(p))return;page=p;search='';riskFilter='All';render();$('sidebar').classList.remove('open');window.scrollTo(0,0)}function modal(title,body){$('modalRoot').innerHTML=`<div class="dialog" id="modal" role="presentation"><div class="dialog-box" role="dialog" aria-modal="true" aria-label="${escapeHtml(title)}"><div class="dialog-head"><h2>${escapeHtml(title)}</h2><button class="btn sm" data-action="close" aria-label="Close dialog">✕</button></div>${body}</div></div>`;let x=$('modal').querySelector('input,textarea,button');if(x)x.focus()}function close(){ $('modalRoot').innerHTML=''}
function csv(rows,name){let s=rows.map(r=>r.map(x=>'"'+safeCSV(x).replaceAll('"','""')+'"').join(',')).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([s],{type:'text/csv;charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function act(a){if(a==='close'){close();return}if(a.startsWith('go:')){go(a.slice(3));return}if(a==='newIncident'){modal('Create synthetic disruption case',`<form id="incidentForm"><label class="field">Incident title</label><input class="control" name="title" required maxlength="120"><label class="field">Severity</label><select class="control" name="severity"><option>Low</option><option>Medium</option><option>High</option></select><label class="field">Owner</label><input class="control" name="owner" value="Network Operations" required><label class="field">Notes</label><textarea class="control" name="notes" required></textarea><button class="btn primary" style="margin-top:17px" type="submit">Create synthetic case</button></form>`);return}if(a.startsWith('flight:')){let f=state.flights.find(x=>x.id===a.slice(7));if(f)modal('Flight record · '+f.id,`<div class="list">${Object.entries(f).map(([k,v])=>`<div class="listrow"><strong>${escapeHtml(k)}</strong><span>${escapeHtml(v)}</span></div>`).join('')}</div><p class="footnote">Synthetic data only. No real Emirates flight record.</p>`);return}if(a.startsWith('incident:')){let x=state.incidents.find(y=>y.id===a.slice(9));if(x)modal('Manage case · '+x.id,`<p>${escapeHtml(x.title)}</p><form id="statusForm" data-id="${escapeHtml(x.id)}"><label class="field">Status</label><select class="control" name="status">${['Open','Investigating','Recovery proposed','Resolved'].map(s=>`<option ${s===x.status?'selected':''}>${s}</option>`).join('')}</select><label class="field">Decision note</label><textarea class="control" name="note" required>${escapeHtml(x.notes)}</textarea><button class="btn primary" style="margin-top:15px">Save local update</button></form>`);return}if(a.startsWith('approval:')){let x=state.approvals.find(y=>y.id===a.slice(9));if(x)modal('Human decision review · '+x.id,`<p>${escapeHtml(x.title)}</p><form id="approvalForm" data-id="${escapeHtml(x.id)}"><label class="field">Decision rationale (required)</label><textarea class="control" name="rationale" required minlength="8" placeholder="Explain your decision"></textarea><div class="toolbar"><button class="btn primary" type="submit" name="decision" value="Approved">Approve simulation</button><button class="btn danger" type="submit" name="decision" value="Rejected">Reject simulation</button></div></form>`);return}if(a.startsWith('scenario:')){selectedScenario=a.slice(9);notify('Scenario '+selectedScenario+' selected for demonstration');return}if(a.startsWith('review:')){let id=a.slice(7),s=scenarios.find(x=>x.id===id);if(!s?.feasible){notify('Infeasible scenario cannot be submitted');return}let item={id:'APR-'+Date.now().toString().slice(-6),title:'Recovery scenario '+id+': '+s.name,status:'Pending',owner:role,rationale:''};state.approvals.unshift(item);audit('approval.requested',item.id+' · Scenario '+id);go('Human approvals');notify('Synthetic approval request created');return}if(a.startsWith('agent:')){let i=Number(a.slice(6));modal('Agent contract · '+AGENTS[i],`<p class="muted">Required: scoped tools, policy decisions, source provenance, durable checkpointing, execution trace, error handling, cost controls, and explicit human approval for consequential actions.</p><div class="banner">Interface specification only. No AI execution.</div>`);return}if(a.startsWith('domain:')){let i=Number(a.slice(7));modal('Data domain · '+DOMAINS[i],`<p class="muted">Required: owner, legal basis, source license, freshness SLO, schema, event-time semantics, quality rules, lineage, retention, access policy, monitoring and replay tests.</p><div class="banner">Catalog definition only; no live data connector.</div>`);return}if(a==='exportFlights'){csv([['id','route','aircraft','gate','eta','delay','risk','status'],...state.flights.map(x=>Object.values(x))],'ain_synthetic_flights.csv');notify('Synthetic flights exported');return}if(a==='exportDomains'){csv([['number','data_domain','status'],...DOMAINS.map((x,i)=>[i+1,x,'Design only'])],'ain_data_domains.csv');notify('Catalog exported');return}if(a==='exportAudit'){csv([['time','event','detail'],...state.audit.map(x=>[x.time,x.event,x.detail])],'ain_browser_audit_demo.csv');notify('Browser audit exported');return}if(a==='exportData'){csv([['domain','records'],['flights',state.flights.length],['incidents',state.incidents.length],['approvals',state.approvals.length],['data domains',DOMAINS.length]],'ain_demo_summary.csv');notify('Summary exported');return}}
document.addEventListener('click',e=>{let p=e.target.closest('[data-page]'),a=e.target.closest('[data-action]');if(p)go(p.dataset.page);if(a)act(a.dataset.action);if(e.target.id==='modal')close()});document.addEventListener('submit',e=>{if(e.target.id==='loginForm'){e.preventDefault();role=$('role').value;$('login').classList.add('hidden');$('app').classList.remove('hidden');audit('demo.session','Demo persona: '+role);render();notify('Welcome · independent aviation simulation');return}if(e.target.id==='incidentForm'){e.preventDefault();let f=new FormData(e.target);let x={id:'SIM-'+Date.now().toString().slice(-6),title:String(f.get('title')),severity:String(f.get('severity')),owner:String(f.get('owner')),status:'Open',notes:String(f.get('notes'))};state.incidents.unshift(x);audit('incident.created',x.id+' '+x.title);close();go('Incident command');notify('Synthetic incident created');return}if(e.target.id==='statusForm'){e.preventDefault();let x=state.incidents.find(x=>x.id===e.target.dataset.id);if(x){let f=new FormData(e.target);x.status=String(f.get('status'));x.notes=String(f.get('note'));audit('incident.updated',x.id+' '+x.status)}close();render();notify('Case updated in browser');return}if(e.target.id==='approvalForm'){e.preventDefault();let x=state.approvals.find(x=>x.id===e.target.dataset.id);if(x){let f=new FormData(e.target,e.submitter);x.status=String(f.get('decision'));x.rationale=String(f.get('rationale'));audit('approval.'+x.status.toLowerCase(),x.id+' '+x.rationale)}close();render();notify('Simulated decision recorded');return}});document.addEventListener('input',e=>{if(e.target.id==='filterText'){search=e.target.value;let pos=e.target.selectionStart;render();let el=$('filterText');if(el){el.focus();el.setSelectionRange(pos,pos)}}});document.addEventListener('change',e=>{if(e.target.id==='riskFilter'){riskFilter=e.target.value;render()}});document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('globalSearch').focus()}});$('menu').onclick=()=>$('sidebar').classList.toggle('open');$('theme').onclick=()=>document.body.classList.toggle('light');$('export').onclick=()=>act('exportData');$('logout').onclick=()=>{state=structuredClone(SEED);page='Executive overview';$('app').classList.add('hidden');$('login').classList.remove('hidden');notify('Demo reset; browser data cleared')};


AGENTS.splice(0,AGENTS.length,'Flight Operations','Aircraft Maintenance','Weather Intelligence','Aviation Safety','Passenger Experience','Predictive Intelligence','Data Analytics','Optimization','Evidence Research','Governance and Approval');
const DISPLAY_NAMES=Object.fromEntries(navNames.map(n=>[n,n]));
const ICONS=['M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z','M3 12h18 M12 3l4 9-4 9-1-8-8-1 8-1z','M12 3L2 21h20z M12 9v5 M12 17v1','M3 6h8v6H3z M13 12h8v6h-8z M11 9h6v3','M9 12l2 2 5-5 M12 2l8 4v6c0 5-8 9-8 9s-8-4-8-9V6z','M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 3a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M18 8v6 M15 11h6','M3 4h7l2 2h9v14H3z M7 10h10 M7 14h8','M4 5h6v6H4z M14 13h6v6h-6z M10 8h7v5 M7 11v6h7','M4 20V9 M10 20V4 M16 20v-8 M22 20H2','M3 5c0-4 18-4 18 0v14c0 4-18 4-18 0z M3 5c0 4 18 4 18 0 M3 12c0 4 18 4 18 0','M12 8v5l4 2 M3 12a9 9 0 1 0 3-7 M3 3v5h5','M12 2l8 4v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6'];
const DOCS=[{id:'SIM-WX-01',title:'Weather capacity exercise',text:'Synthetic exercise: a reduced arrival acceptance rate increases delay exposure on the simulated Singapore and Paris rotations. This is a scenario assumption, not a current weather observation.',kind:'Simulation assumption',date:'19 Nov 2026'},{id:'SIM-OPS-02',title:'Recovery review procedure',text:'Compare delay, connection exposure and resource constraints. Reject infeasible plans. A human reviewer must record a reason before a simulated decision is marked reviewed. An approved demonstration does not alter any airline schedule.',kind:'Demo procedure',date:'19 Nov 2026'},{id:'SIM-CX-03',title:'Passenger insight definitions',text:'Negative feedback themes are indicators of reported experience, not survey satisfaction or proven operational causes. Compare complaint rates only when periods and passenger denominators match. Protect small sensitive groups.',kind:'Demo metric definition',date:'19 Nov 2026'}];
const FEEDBACK=[{id:'CX-001',theme:'Connection information',rating:'Negative',text:'The inbound flight was late and the connection information was hard to find.'},{id:'CX-002',theme:'Baggage updates',rating:'Negative',text:'I needed clearer updates about where to collect my delayed baggage.'},{id:'CX-003',theme:'Service recovery',rating:'Positive',text:'The airport team explained the next steps and helped with the connection.'},{id:'CX-004',theme:'Connection information',rating:'Negative',text:'The gate change and revised boarding time were confusing.'},{id:'CX-005',theme:'Service recovery',rating:'Positive',text:'The staff kept us informed throughout the disruption.'},{id:'CX-006',theme:'Accessibility support',rating:'Neutral',text:'Assistance was available, but the meeting point could have been clearer.'}];
let workflowPreview=false, evidenceQuery='', lastFocus=null;
try{const saved=JSON.parse(localStorage.getItem('ain-full-ui-v1')||'null');if(saved&&Array.isArray(saved.flights)&&Array.isArray(saved.incidents)&&Array.isArray(saved.approvals)&&Array.isArray(saved.audit))state=saved}catch{}
audit=function(event,detail){state.audit.unshift({time:now(),event,detail});try{localStorage.setItem('ain-full-ui-v1',JSON.stringify(state))}catch{}};
head=function(title,desc,actions=''){return `<div class="title-row"><div><div class="eyebrow">Aviation Intelligence Nexus</div><h2>${escapeHtml(DISPLAY_NAMES[title]||title)}</h2><div class="muted">${escapeHtml(desc)}</div></div><div class="toolbar">${actions}</div></div>`};
overview=function(){const high=state.flights.filter(f=>f.risk==='High').length,delay=state.flights.reduce((n,f)=>n+f.delay,0),pending=state.approvals.filter(x=>x.status==='Pending').length;return `<section class="hero"><div class="hero-copy"><div class="eyebrow">Network decision workspace</div><h1>Clarity before the next decision.</h1><p>Understand disruption exposure, inspect the evidence and compare recovery options in one workspace.</p></div><button class="btn primary" data-page="Recovery optimizer">Compare recovery plans</button></section><div class="grid kpis">${kpi('Flights in this exercise',state.flights.length,'Synthetic Dubai hub sample')}${kpi('High-risk flights',high,'Scenario labels · no trained model')}${kpi('Illustrative delay',delay+' min','Sum across the displayed flight sample')}${kpi('Awaiting review',pending,'Local demo decisions')}</div><div class="split"><section class="card"><div class="panel-title"><h3>Network exposure</h3><span class="pill info">Illustrative routes</span></div>${MAP}<div class="footnote">Fixed exercise snapshot · 19 Nov 2026, 12:00 UTC. Route positions are illustrative.</div></section><section class="card"><div class="panel-title"><h3>Requires attention</h3><button class="btn sm ghost" data-page="Incident command">View cases</button></div>${state.incidents.filter(x=>x.status!=='Resolved').map(x=>`<div class="listrow"><div><strong>${escapeHtml(x.title)}</strong><small>${escapeHtml(x.id)} · ${escapeHtml(x.owner)}</small></div>${pill(x.severity)}</div>`).join('')||'<p class="muted">No open cases in this local exercise.</p>'}<div class="listrow"><div><strong>Review recovery alternatives</strong><small>${pending} decisions require a recorded rationale</small></div><button class="btn sm" data-page="Human approvals">Review</button></div><div class="source-card"><h4>Evidence before action</h4><p>Open the source assumptions before accepting a scenario.</p><button class="btn sm" data-page="Evidence & RAG">Inspect evidence</button></div></section></div><div class="section-title"><h3>Flight watchlist</h3><button class="btn sm" data-page="Live flight board">Open flight operations</button></div>${flightTable()}<div class="section-title"><h3>Intelligence capability status</h3></div><div class="grid agent-grid">${[['Predictive data science','Targets and evaluation specified. Model training and serving are not connected.','Model evaluation'],['Evidence-grounded assistance','Inspect cited demo procedures. Production retrieval and generation remain to be built.','Evidence & RAG'],['Governed agent workflows','Preview tool boundaries and human review. No autonomous airline actions.','AI agent command']].map(x=>`<div class="card"><h3>${x[0]}</h3><p class="muted" style="font-size:14px">${x[1]}</p><button class="btn sm" data-page="${x[2]}">Explore workspace</button></div>`).join('')}</div>`};
function passengerView(){const neg=FEEDBACK.filter(x=>x.rating==='Negative').length;return head(page,'Understand reported experience and recurring service issues')+`<div class="banner">All six feedback records below are written demo fixtures. Sentiment and themes are manually assigned; no classifier or clustering model has run.</div><div class="grid kpis">${kpi('Feedback fixtures',FEEDBACK.length,'Not a passenger population')}${kpi('Negative examples',neg,'Manual labels, not inferred sentiment')}${kpi('Issue themes',new Set(FEEDBACK.map(x=>x.theme)).size,'Manually assigned categories')}${kpi('Complaint rate','Unavailable','No passenger denominator supplied')}</div><div class="split"><section class="card"><h3>Recurring issues in this exercise</h3>${[...new Set(FEEDBACK.map(x=>x.theme))].map(theme=>{let n=FEEDBACK.filter(x=>x.theme===theme).length;return `<div class="metric-row"><span>${escapeHtml(theme)}</span><strong>${n}</strong></div>`}).join('')}<p class="footnote">Production trend analysis needs comparable time windows and stable labels. This fixture cannot establish a time trend.</p></section><section class="card"><h3>Required model evaluation</h3><div class="listrow"><strong>Sentiment classification</strong>${pill('Not evaluated')}</div><div class="listrow"><strong>Issue clustering</strong>${pill('Not evaluated')}</div><div class="listrow"><strong>Service trend detection</strong>${pill('Not evaluated')}</div><p class="footnote">Use licensed airline feedback, a reviewed gold set, time-based splits and cohort error analysis.</p><button class="btn sm" data-page="Model evaluation">View evaluation plan</button></section></div><div class="section-title"><h3>Feedback evidence</h3></div>${gridRows(['Record','Theme','Manual label','Feedback'],FEEDBACK.map(x=>[x.id,escapeHtml(x.theme),pill(x.rating),escapeHtml(x.text)]))}`}
function evidenceView(){return head(page,'Inspect evidence and provenance before forming an answer')+`<div class="split"><section class="card"><h3>Ask about this exercise</h3><form id="evidenceForm"><label class="field" for="evidenceQuestion">Investigation question</label><textarea class="control" id="evidenceQuestion" required maxlength="1000" placeholder="What needs review before a recovery plan is accepted?">${escapeHtml(evidenceQuery)}</textarea><div class="toolbar"><button class="btn primary" type="submit">Find demo evidence</button><button class="btn" type="button" data-action="evidenceExample">Use example</button></div></form><p class="footnote">Local keyword retrieval over three fixtures. This is an evidence interaction prototype; an LLM is not connected.</p><div id="evidenceAnswer" aria-live="polite"></div></section><section class="card"><h3>Source register</h3>${DOCS.map(d=>`<div class="source-card"><h4>${d.id} · ${d.title}</h4><div class="small">${d.kind} · ${d.date}</div><p>${escapeHtml(d.text)}</p></div>`).join('')}</section></div>`}
function workflowView(){return head(page,'A bounded investigation with evidence and a human checkpoint',button('Preview workflow','previewWorkflow'))+`<div class="banner">Local workflow simulation only. LangGraph, LLM providers, durable server checkpoints and secure approval services are not connected.</div><div class="split"><section class="card"><h3>Disruption investigation</h3><div class="timeline">${[['Read the operational snapshot','Flight Operations · scoped fixture lookup'],['Inspect capacity assumptions','Weather Intelligence · source SIM-WX-01'],['Compare candidate plans','Optimization · hand-authored scenarios'],['Verify and request review','Governance · human decision checkpoint']].map((x,i)=>`<div class="step"><span class="step-num">${i+1}</span><div><strong>${x[0]}</strong><div class="small">${x[1]}</div></div>`).join('')}</div><div class="toolbar"><button class="btn primary" data-action="previewWorkflow">Preview local trace</button><button class="btn" data-page="Human approvals">Open review queue</button></div></section><section class="card"><h3>Execution trace</h3>${workflowPreview?`<div class="source-card"><h4>Local demonstration trace</h4><p>Looked up ${state.flights.length} flight fixtures; ${state.flights.filter(x=>x.risk==='High').length} have a High scenario label.</p><p>Evidence: SIM-WX-01 and SIM-OPS-02.</p><p>Loaded candidate plans A, B and C. Candidate C is marked infeasible by the fixture author.</p><p><strong>Paused for a human review.</strong> No plan has been executed or approved automatically.</p></div>`:'<div class="empty">Preview the workflow to inspect its local steps.</div>'}<div class="metric-row"><span>LLM calls</span><strong>0</strong></div><div class="metric-row"><span>Airline write access</span><strong>None</strong></div><div class="metric-row"><span>Server execution</span><strong>Not connected</strong></div></section></div><div class="section-title"><h3>Specialist roles</h3></div><div class="grid agent-grid">${AGENTS.map((x,i)=>`<div class="card"><div class="eyebrow">Role specification</div><h3>${escapeHtml(x)}</h3><p class="small">Typed tools, scoped permissions, evidence references, deadlines and failure behavior.</p>${button('Inspect contract','agent:'+i)}</div>`).join('')}</div>`}
function modelsView(){return head(page,'Evaluation requirements and evidence needed before model promotion')+gridRows(['Use case','Baseline','Required evaluation','Status'],[['Arrival delay risk','Historical rate + logistic regression','Later-period PR-AUC, calibration, slices',pill('Not evaluated')],['Delay duration','Route/time median','MAE, prediction interval coverage',pill('Not evaluated')],['Engine benchmark RUL','Simple degradation baseline','Engine-group split; MAE and late-error cost',pill('Not evaluated')],['Passenger sentiment','TF-IDF + linear classifier','Reviewed labels; macro-F1; language slices',pill('Not evaluated')],['Recurring feedback themes','TF-IDF topic grouping','Human coherence, stability and usefulness',pill('Not evaluated')]])+`<div class="banner">The source documents specify model methods and targets. No trained artifacts or measured evaluation reports were supplied for this review.</div><div class="card"><h3>Promotion contract</h3><p class="muted">Bind each promoted model to a source snapshot, feature schema, code revision, temporal split, model card and measured evaluation. Test the fallback and rollback path.</p></div>`}
flights=function(){return head(page,'Search, filter, inspect and export synthetic flight records')+flightControls()+flightTable()+'<div class="banner">Historical replay or synthetic fixtures only. No live airline source is connected.</div>'};
const originalAct=act;
act=function(action){if(action==='previewWorkflow'){workflowPreview=true;audit('demo.workflow.preview','Deterministic local fixture trace; no LLM or airline action');render();notify('Local trace ready; human review remains required');return}if(action==='evidenceExample'){const x=document.getElementById('evidenceQuestion');x.value='What needs human review before a recovery plan is accepted?';x.focus();return}originalAct(action)};
render=function(){document.title='AIN | '+(DISPLAY_NAMES[page]||page);$('breadcrumb').textContent=DISPLAY_NAMES[page]||page;let i=0;$('nav').innerHTML=Object.entries(MODULES).map(([group,names])=>`<div class="nav-section">${group}</div>`+names.map(name=>{let icon=ICONS[i++%ICONS.length];return `<button class="nav-item ${page===name?'active':''}" data-page="${escapeHtml(name)}" ${page===name?'aria-current="page"':''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icon}"/></svg><span>${DISPLAY_NAMES[name]||name}</span>${name==='Human approvals'?'<span class="count">'+state.approvals.filter(x=>x.status==='Pending').length+'</span>':''}</button>`}).join('')).join('');const view=page==='Executive overview'?overview():page==='Live flight board'?flights():page==='Incident command'?incidents():page==='Recovery optimizer'?recovery():page==='Human approvals'?approvals():page==='Customer experience'?passengerView():page==='Evidence & RAG'?evidenceView():page==='AI agent command'?workflowView():page==='Model evaluation'?modelsView():page==='Data operations catalog'?domains():page==='Audit trail'?auditPage():enterprise();$('content').innerHTML=`<div class="context"><div><div class="context-label">Independent simulation</div><p>Dubai hub exercise · fixed snapshot · UTC</p></div><div class="toolbar"><button class="btn sm" data-page="Evidence & RAG">View source assumptions</button><button class="btn sm" data-page="Release management">Readiness status</button></div></div>`+view+`<div class="footer-note">Independent reference prototype. Synthetic operational data. No airline affiliation, live feed, trained model, secure identity service or production approval endpoint is connected.</div>`;};
const originalGo=go;
go=function(p){originalGo(p);document.body.classList.remove('nav-open');$('menu').setAttribute('aria-expanded','false');$('content').focus({preventScroll:true});syncNavigationInert()};
modal=function(title,body){lastFocus=document.activeElement;$('modalRoot').innerHTML=`<div class="dialog" id="modal"><div class="dialog-box" role="dialog" aria-modal="true" aria-labelledby="dialogTitle"><div class="dialog-head"><h2 id="dialogTitle">${escapeHtml(title)}</h2><button class="btn sm" data-action="close" aria-label="Close dialog">Close</button></div>${body}</div></div>`;document.querySelectorAll('.dialog-box label.field').forEach((label,i)=>{const field=label.nextElementSibling;if(field&&['INPUT','TEXTAREA','SELECT'].includes(field.tagName)){field.id=field.id||('dialog-field-'+i);label.htmlFor=field.id}});document.querySelector('.dialog-box')?.querySelector('button,input,textarea,select')?.focus()};
close=function(){$('modalRoot').innerHTML='';if(lastFocus?.isConnected)lastFocus.focus();else $('content').focus({preventScroll:true});syncNavigationInert()};
document.addEventListener('keydown',e=>{const modalEl=document.querySelector('.dialog-box');if(e.key==='Tab'&&modalEl){const items=[...modalEl.querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}if(e.key==='Escape'){document.body.classList.remove('nav-open');$('sidebar').classList.remove('open');$('menu').setAttribute('aria-expanded','false')}});
document.addEventListener('submit',e=>{if(e.target.id!=='evidenceForm')return;e.preventDefault();evidenceQuery=$('evidenceQuestion').value.trim();const words=evidenceQuery.toLowerCase().match(/[a-z]{4,}/g)||[];const results=DOCS.map(d=>({d,score:words.filter(w=>(d.title+' '+d.text).toLowerCase().includes(w)).length})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,2);$('evidenceAnswer').innerHTML=results.length?'<h3 style="margin-top:24px">Retrieved fixture evidence</h3>'+results.map(({d})=>`<div class="source-card"><h4>[${d.id}] ${escapeHtml(d.title)}</h4><p>${escapeHtml(d.text)}</p><div class="small">Exact fixture excerpt · ${d.date}</div></div>`).join(''):'<div class="banner">Insufficient evidence in the three demo fixtures. No answer was generated.</div>';audit('demo.evidence.search',results.length+' matching fixture sources')});
$('menu').onclick=()=>{const open=$('sidebar').classList.toggle('open');document.body.classList.toggle('nav-open',open);$('menu').setAttribute('aria-expanded',String(open));syncNavigationInert()};$('navBackdrop').onclick=()=>{$('sidebar').classList.remove('open');document.body.classList.remove('nav-open');$('menu').setAttribute('aria-expanded','false');syncNavigationInert()};$('theme').onclick=()=>document.body.classList.toggle('dark');$('logout').onclick=()=>{state=structuredClone(SEED);workflowPreview=false;localStorage.removeItem('ain-full-ui-v1');go('Executive overview');notify('Synthetic demonstration reset')};
