// End-to-end UI preparation. Every run is an explicitly local, manually advanced rehearsal.
const STUDIO_KEY='ain-delivery-ui-v2';
function studioSeed(){return {version:2,sources:[],pipelines:[],models:structuredClone(STUDIO_MODELS),documents:[],policies:[],runs:[],evidence:{},monitors:[],drills:[],tests:[],releases:[],apiContracts:[],permissions:{},constraints:{delay:120,connections:40,cost:160,objective:'connections'},constraintVersion:1,bindings:{},qualityResult:null,apiResult:null,lineageNode:0,checkResult:null}}
let studio=studioSeed();
try{const raw=JSON.parse(localStorage.getItem(STUDIO_KEY)||'null');if(raw&&raw.version===2)studio={...studio,...raw}}catch{}
const studioRouteArea=n=>STUDIO_AREAS.find(a=>a.id===(STUDIO_ROUTE_AREA[n]||'workflows'));
const studioCounts=()=>({runs:studio.runs.length,requirements:STUDIO_AREAS.reduce((n,a)=>n+a.requirements.length,0),submitted:Object.keys(studio.evidence).length});
const studioNow=()=>new Date().toISOString();
const studioId=prefix=>prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);
function studioSave(){try{localStorage.setItem(STUDIO_KEY,JSON.stringify(studio))}catch{notify('Local storage is full or unavailable. Export your work before closing this page.')}}
function studioButton(label,action,primary=false,disabled=false){return `<button class="btn ${primary?'primary':''}" data-action="studio:${action}" ${disabled?'disabled':''}>${escapeHtml(label)}</button>`}
function studioHead(title,description,mode='Local UI rehearsal'){return `<section class="studio-intro"><div><div class="eyebrow">AVIATION INTELLIGENCE NEXUS / ${escapeHtml(studioRouteArea(page).title)}</div><h2>${escapeHtml(title)}</h2><p>${escapeHtml(description)}</p></div><span class="studio-mode">${escapeHtml(mode)}</span></section>`}
function studioTable(headers,rows,caption='Workspace exercise records'){return `<div class="table-wrap"><table class="studio-table"><caption class="sr-only">${escapeHtml(caption)}</caption><thead><tr>${headers.map(h=>`<th scope="col">${escapeHtml(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}"><div class="studio-empty">No local records yet. Create a draft to explore this workflow.</div></td></tr>`}</tbody></table></div>`}
function studioStats(items){return `<div class="studio-summary">${items.map(([label,value,note])=>`<div class="studio-stat"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong><small>${escapeHtml(note)}</small></div>`).join('')}</div>`}
function studioSection(title,description='',action=''){return `<div class="studio-section"><div><h3>${escapeHtml(title)}</h3>${description?'<p>'+escapeHtml(description)+'</p>':''}</div>${action}</div>`}
function studioBoundary(message='This is a local UI exercise. No production service is connected and no operational action is executed.'){return `<div class="studio-inline-warning">${escapeHtml(message)}</div>`}
function studioRowsFallback(){return `<details class="studio-details"><summary>Workspace record register · create, edit, filter, export and archive</summary>${domainView(page)}</details>`}
function studioAreaCards(){return `<div class="studio-grid">${STUDIO_AREAS.map(a=>`<section class="studio-card"><div class="eyebrow">${escapeHtml(a.owner)}</div><h3>${escapeHtml(a.title)}</h3><p>${escapeHtml(a.summary)}</p><span class="pill">${a.requirements.length} acceptance requirements</span><button class="btn" data-page="${escapeHtml(a.route)}">Open workspace</button></section>`).join('')}</div>`}
function studioScope(){modal('Complete platform scope',`<p class="studio-prose">Your aviation platform covers data science, generative AI, agentic AI and operations research, supported by data engineering, governance and reliable delivery. All 64 workspaces remain available.</p>${studioStats([['Original workspaces',64,'Eight preserved departments'],['Scope requirements',studioCounts().requirements,'Twelve implementation areas'],['Connected backend services',0,'No server integrations supplied'],['Local rehearsals',studio.runs.length,'Not real execution']])}${studioAreaCards()}${studioBoundary('UI coverage and local rehearsal do not establish production readiness. Production evidence must come from implemented and independently verified services.')}`);document.querySelector('.dialog-box').classList.add('studio-scope-dialog')}
function studioReadinessView(){const a=studioRouteArea(page);return studioHead(page+' · acceptance','Requirements, ownership and evidence for this workspace. Local review decisions are exercise records.')+`<div class="studio-strip"><span>Owner: <strong>${escapeHtml(reg(page).owner)}</strong></span><span>Area: <strong>${escapeHtml(a.title)}</strong></span><span>Backend: <strong>Not connected</strong></span></div><section class="card"><h3>Implementation acceptance checklist</h3>${a.requirements.map((r,i)=>studioEvidenceRow(a.id+'-'+i,r)).join('')}</section>${studioSection('Connected workflow',reg(page).description)}${relatedWorkspaces(page)}${studioBoundary('Submitting or accepting local evidence cannot certify production behavior. Actual API, data, model, security and recovery results must be verified during implementation.')}`}
function studioEvidenceRow(key,title){const e=studio.evidence[key];return `<div class="studio-evidence-item"><div><h4>${escapeHtml(title)}</h4><p>${e?escapeHtml(e.status+' · '+e.owner):'Evidence not submitted'}</p>${e?'<small class="studio-toolbar-note">'+escapeHtml(e.reference)+'</small>':''}</div>${studioButton(e?'Review evidence':'Add evidence','evidence:'+key)}</div>`}
