function studioForm(type){const cfg=STUDIO_FORMS[type];if(!cfg)return;modal(cfg.title,`<p class="studio-form-note">Create a browser-local design record. Use synthetic information; do not enter credentials or personal data.</p><form id="studioCreateForm" data-type="${type}"><div class="studio-form-grid">${cfg.fields.map(([name,label,kind,initial])=>`<div class="${kind==='textarea'?'full-width':''}"><label class="field" for="studio-${name}">${escapeHtml(label)}</label>${kind==='select'?`<select id="studio-${name}" name="${name}" class="control">${initial.map(v=>`<option>${escapeHtml(v)}</option>`).join('')}</select>`:kind==='textarea'?`<textarea id="studio-${name}" name="${name}" class="control" required maxlength="6000">${escapeHtml(initial)}</textarea>`:`<input id="studio-${name}" name="${name}" type="${kind}" class="control" value="${escapeHtml(initial)}" required maxlength="500" ${kind==='number'?'min="0" max="100000" step="1"':''}>`}</div>`).join('')}</div><div class="studio-dialog-foot"><button class="btn primary">Save local draft</button><button class="btn" type="button" data-action="close">Cancel</button></div></form>`)}
const STUDIO_STAGES={pipeline:['Validate source contract','Preview schema and deduplication','Preview quarantine handling','Checkpoint target write','Record rehearsal outcome'],stream:['Select replay cutoff','Preview event ordering','Preview deduplication','Checkpoint replay cursor','Record rehearsal outcome'],training:['Pin dataset release and split','Check baseline configuration','Preview training job submission','Preview evaluation checkpoint','Record missing measured artifacts'],document:['Review rights and source version','Preview extraction','Preview chunks and metadata','Preview embedding submission','Record indexing rehearsal'],agent:['Read the fixed flight snapshot','Retrieve eligible fixture evidence','Inspect recovery assumptions','Prepare a proposed action','Pause for human review'],deployment:['Review candidate and evidence gates','Preview build and migration checks','Preview staging rollout','Preview health and canary checks','Record rollout rehearsal'],drill:['Select isolated restore target','Preview backup selection','Preview restoration','Preview reconciliation and access checks','Record unmeasured recovery outcome'],test:['Load test setup','Preview test environment','Preview execution checkpoint','Capture expected-result review','Record missing real test results']};
function studioStartRun(kind,reference=''){modal('Start '+({training:'model experiment',agent:'agent investigation',pipeline:'pipeline rehearsal',stream:'stream replay',document:'document processing',deployment:'deployment rehearsal',drill:'recovery rehearsal',test:'test rehearsal'}[kind]||'workflow'),`<p class="studio-form-note">This previews job lifecycle and checkpoints. It does not call a provider, process a large dataset, train a model or deploy services.</p><form id="studioRunForm" data-kind="${kind}"><label class="field" for="studioRunName">Run name</label><input class="control" id="studioRunName" name="name" value="${escapeHtml((reference||page)+' · UI rehearsal')}" required maxlength="250"><label class="field" for="studioRunReference">Source / configuration reference</label><input class="control" id="studioRunReference" name="reference" value="${escapeHtml(reference||'Synthetic exercise snapshot')}" required maxlength="400"><label class="field" for="studioRunFailure">Failure rehearsal</label><select class="control" id="studioRunFailure" name="failure"><option value="none">No injected failure</option><option value="source">Source unavailable at first checkpoint</option><option value="timeout">Dependency timeout at second checkpoint</option></select><div class="studio-dialog-foot"><button class="btn primary">Queue local rehearsal</button><button class="btn" type="button" data-action="close">Cancel</button></div></form>`)}
function studioRunDetail(id){const run=studio.runs.find(r=>r.id===id);if(!run)return;const stages=STUDIO_STAGES[run.kind];modal('Run detail · '+run.name,`<div class="studio-strip"><span>${pill(run.status)}</span><span>Checkpoint: <strong>${run.step} / ${stages.length}</strong></span><span>Attempt: <strong>${run.attempt}</strong></span></div><p class="small">${escapeHtml(run.reference)} · Durable only in this browser.</p><ol class="studio-trace">${stages.map((s,i)=>`<li class="${i<run.step?'done':i===run.step?'current':''}"><strong>${escapeHtml(s)}</strong><small>${i<run.step?'UI checkpoint recorded':i===run.step?'Next rehearsal checkpoint':'Not reached'}</small></li>`).join('')}</ol><div class="studio-actions">${run.status==='Queued'?studioButton('Start rehearsal','runStart:'+id,true):''}${run.status==='Running'?studioButton('Advance checkpoint','runNext:'+id,true)+studioButton('Pause','runPause:'+id)+studioButton('Inject failure','runFail:'+id):''}${run.status==='Paused'?studioButton('Resume rehearsal','runResume:'+id,true):''}${run.status==='Failed'?studioButton('Retry from checkpoint','runRetry:'+id,true):''}${run.status==='Awaiting human review'?'<button class="btn primary" data-page="Human approvals">Open human review queue</button>':''}${['Queued','Running','Paused','Failed','Awaiting human review'].includes(run.status)?studioButton('Cancel rehearsal','runCancel:'+id):''}${studioButton('Export run trace','runExport:'+id)}</div><div class="studio-log" aria-label="Local run trace">${escapeHtml(run.log.join('\n'))}</div>${studioBoundary(run.status==='UI rehearsal complete'?'Only UI checkpoints completed. No actual model artifact, provider response, deployed service or measured recovery result was produced.':'The trace records interface actions. No agent runtime, database worker or deployment executor is connected.')}`)}
function studioRunList(kinds){const runs=studio.runs.filter(r=>kinds.includes(r.kind));return studioTable(['Run / source','Lifecycle state','Checkpoint','Details'],runs.map(r=>[escapeHtml(r.name)+'<small>'+escapeHtml(r.reference)+'</small>',pill(r.status),r.step+' / '+STUDIO_STAGES[r.kind].length,studioButton('Inspect run','run:'+r.id)]),'Local job rehearsals')}
function studioRunTransition(key,id){const r=studio.runs.find(x=>x.id===id);if(!r)return;let message='';if(key==='runStart'&&r.status==='Queued'){r.status='Running';message='Rehearsal started'}else if(key==='runPause'&&r.status==='Running'){r.status='Paused';message='Checkpoint retained; paused locally'}else if(key==='runResume'&&r.status==='Paused'){r.status='Running';message='Resumed from local checkpoint'}else if(key==='runFail'&&r.status==='Running'){r.status='Failed';message='Injected dependency failure; checkpoint retained'}else if(key==='runRetry'&&r.status==='Failed'){r.status='Running';r.attempt++;r.failure='none';message='Retry accepted; no external call made'}else if(key==='runCancel'&&['Queued','Running','Paused','Failed','Awaiting human review'].includes(r.status)){r.status='Cancelled';message='Cancelled locally; no pending server request'}else if(key==='runNext'&&r.status==='Running'){if((r.failure==='source'&&r.step===0)||(r.failure==='timeout'&&r.step===1)){r.status='Failed';message='Injected '+r.failure+' failure; previous checkpoint retained'}else{r.step++;message='UI checkpoint recorded: '+STUDIO_STAGES[r.kind][r.step-1];if(r.step===STUDIO_STAGES[r.kind].length){r.status=r.kind==='agent'?'Awaiting human review':'UI rehearsal complete';message+='; no operational execution'}}}else return;r.updated=studioNow();r.log.push(r.updated+' '+message);studioSave();render();studioRunDetail(id)}
function studioPipelineView(){return studioHead('From source to trusted snapshot','Configure ingestion, inspect quality boundaries and rehearse resumable processing before connecting real data.')+`<div class="studio-actions">${studioButton('Register source','new:source',true)}${studioButton('Configure pipeline','new:pipeline')}${studioButton('Rehearse ingestion','start:pipeline')}${studioButton('Preview JSON validation','json')}</div>`+studioStats([['Source drafts',studio.sources.length,'Rights and release metadata'],['Pipeline drafts',studio.pipelines.length,'No collectors connected'],['Local runs',studio.runs.filter(r=>['pipeline','stream'].includes(r.kind)).length,'Manual UI lifecycle'],['Live ingestion',0,'No real feed connected']])+studioSection('Pipeline configurations','Batch, incremental and streaming designs.')+studioTable(['Pipeline','Mode / source','Target / handling','Action'],studio.pipelines.map(p=>[escapeHtml(p.name),escapeHtml(p.mode)+'<small>'+escapeHtml(p.source)+'</small>',escapeHtml(p.target)+'<small>'+escapeHtml(p.failure)+'</small>',studioButton('Rehearse','start:pipeline:'+p.id)]))+studioSection('Execution lifecycle','Inspect, pause, cancel, fail, retry and resume local checkpoints.')+studioRunList(['pipeline','stream'])+studioRowsFallback()}
function studioDatasetView(){return studioHead('Dataset releases & permissions','Register source rights, coverage, grain and retention before proposing ingestion.')+`<div class="studio-actions">${studioButton('Register dataset','new:source',true)}${studioButton('Validate sample JSON','json')}<button class="btn" data-page="Data access requests">Purpose-bound access</button></div>`+studioTable(['Dataset / domain','Release / coverage','Rights / retention','Status'],studio.sources.map(s=>[escapeHtml(s.name)+'<small>'+escapeHtml(s.domain)+'</small>',escapeHtml(s.release)+'<small>'+escapeHtml(s.coverage)+'</small>',escapeHtml(s.rights)+'<small>'+escapeHtml(s.retention)+'</small>',pill('Unverified local draft')]))+studioBoundary('Registering a source does not grant a license or access. Public aviation datasets can be historical or jurisdiction-specific; they must not be represented as Emirates operational data.')+studioRowsFallback()}
function studioStreamingView(){return studioHead('Event replay & checkpoints','Rehearse late arrivals, duplicate events, source outages and retained replay cursors.')+`<div class="studio-actions">${studioButton('Start replay rehearsal','start:stream',true)}${studioButton('Validate event sample','json')}<button class="btn" data-page="Observability">Review monitoring</button></div>`+`<div class="studio-layout"><section class="card"><h3>Replay contract</h3><ul class="studio-list">${['Separate event time from ingestion time','Use an idempotent source event identifier','Declare the allowed lateness and watermark policy','Preserve a checkpoint before acknowledging writes','Quarantine invalid events with a replayable reason'].map(s=>`<li><span class="check-symbol">•</span><span>${s}</span></li>`).join('')}</ul></section><section class="card"><h3>Service state</h3>${['Event broker','Durable replay cursor','Dead-letter queue','Production consumer'].map(s=>`<div class="studio-integration-row"><span>${s}</span>${pill('Not connected')}</div>`).join('')}</section></div>`+studioSection('Replay rehearsals')+studioRunList(['stream'])+studioRowsFallback()}
function studioModelView(){return studioHead('Model experiments & evaluation','Design measurable aviation models with baselines, valid splits, uncertainty and controlled promotion.')+`<div class="studio-actions">${studioButton('Register experiment','new:model',true)}${studioButton('Rehearse model lifecycle','start:training')}<button class="btn" data-page="Model evaluation">Evaluation requirements</button><button class="btn" data-page="Release management">Promotion gates</button></div>`+studioStats([['Model designs',studio.models.length,'Classification, regression and more'],['Measured model results',0,'No trained artifacts supplied'],['Training rehearsals',studio.runs.filter(r=>r.kind==='training').length,'No training compute invoked'],['Promoted models',0,'Production gate not met']])+studioTable(['Model / task','Target / baseline','Split / metric plan','Action'],studio.models.map(m=>[escapeHtml(m.name)+'<small>'+escapeHtml(m.task)+'</small>',escapeHtml(m.target)+'<small>Baseline: '+escapeHtml(m.baseline)+'</small>',escapeHtml(m.split)+'<small>'+escapeHtml(m.metrics)+'</small>',studioButton('Inspect design','model:'+m.id)]))+studioSection('Training & evaluation lifecycle')+studioRunList(['training'])+studioBoundary('Metrics remain unmeasured. A completed UI rehearsal never registers a trained artifact or makes a model eligible for production.')}
function studioModelDetail(id){const m=studio.models.find(x=>x.id===id);if(!m)return;modal('Model design · '+m.name,`<dl class="record-detail">${[['Task',m.task],['Target',m.target],['Dataset',m.dataset],['Baseline',m.baseline],['Split',m.split],['Metrics',m.metrics],['Artifact','Not supplied'],['Evaluation','Not measured'],['Promotion','Blocked until verified implementation evidence']].map(([k,v])=>`<div><dt>${k}</dt><dd>${escapeHtml(v)}</dd></div>`).join('')}</dl><div class="studio-actions">${studioButton('Rehearse experiment','start:training:'+m.id)}<button class="btn" data-page="Model evaluation">Evaluation workspace</button></div>`)}
function studioEvaluationView(){return studioHead('Model evaluation & promotion','Require later-period performance, cohort errors and measured baseline comparisons before release.')+`<div class="studio-actions">${studioButton('Register experiment','new:model',true)}${studioButton('Attach evaluation evidence','evidence:science-5')}<button class="btn" data-page="Prediction models">Model registry</button></div>`+studioTable(['Use case','Evaluation plan','Current result'],studio.models.map(m=>[escapeHtml(m.name),escapeHtml(m.split)+'<small>'+escapeHtml(m.metrics)+'</small>',pill('Not measured')]))+`<div class="studio-layout" style="margin-top:22px"><section class="card"><h3>Leakage and validity review</h3><ul class="studio-list">${['Features available by the decision cutoff','No entity overlap where unit isolation is required','Baselines evaluated on the same held-out population','Confidence intervals and cohort error analysis','Explicit unsupported regimes and abstention behavior'].map(x=>`<li><span class="check-symbol">•</span><span>${x}</span></li>`).join('')}</ul></section><section class="card"><h3>Promotion evidence</h3>${STUDIO_AREAS.find(a=>a.id==='science').requirements.map((r,i)=>studioEvidenceRow('science-'+i,r)).join('')}</section></div>`+studioRunList(['training'])}
function studioDocumentsView(){return studioHead('Documents, versions & evidence','Preview source eligibility, extraction, chunking and indexing, then inspect evidence in the retrieval workspace.')+`<div class="studio-actions">${studioButton('Register synthetic document','new:document',true)}${studioButton('Rehearse processing','start:document')}<button class="btn" data-page="Evidence & RAG">Search fixture evidence</button></div>`+studioTable(['Document','Version / rights','Local source status','Action'],[...DOCS.map(d=>[escapeHtml(d.title),escapeHtml(d.date)+'<small>Written synthetic fixture</small>',pill('Keyword-search fixture'),studioButton('Inspect source','doc:'+d.id)]),...studio.documents.map(d=>[escapeHtml(d.title),escapeHtml(d.version)+'<small>'+escapeHtml(d.rights)+'</small>',pill('Local document draft'),studioButton('Inspect source','doc:'+d.id)])])+studioSection('Processing rehearsals','Rehearsal does not generate embeddings or update the fixture retrieval corpus.')+studioRunList(['document'])+studioBoundary('New document drafts remain separate from the three-fixture keyword retrieval demo. Permission-aware retrieval, real embeddings and a generative model require backend implementation.')}
function studioAgentsView(){return studioHead('Governed agent investigation','Inspect ten specialist contracts, design policies and rehearse evidence-led tool use with a human checkpoint.')+`<div class="studio-actions">${studioButton('Start investigation rehearsal','start:agent',true)}${studioButton('Draft prompt & tool policy','new:policy')}<button class="btn" data-page="Ten specialist agents">Ten specialist contracts</button><button class="btn" data-page="Human approvals">Human checkpoint</button></div>`+`<div class="studio-lineage">${[['Snapshot','Flight Operations','Typed read-only scope'],['Evidence','Evidence Research','Source ID and version'],['Proposal','Optimization','No operational write'],['Human review','Governance and Approval','No autonomous disposition']].map(([t,r,b],i)=>`<button data-action="studio:agentNode:${i}"><strong>${t}</strong><small>${r}<br>${b}</small></button>`).join('')}</div>`+studioSection('Investigation runs','Run states are manually advanced UI exercises; no model or tool provider is called.')+studioRunList(['agent'])+studioSection('Prompt and tool policy drafts')+studioTable(['Policy / version','Allowed tools','Limits / checkpoint'],studio.policies.map(p=>[escapeHtml(p.name)+'<small>Version '+escapeHtml(p.version)+'</small>',escapeHtml(p.tools),escapeHtml(p.limit)+' calls maximum<small>'+escapeHtml(p.approval)+'</small>']))+studioBoundary('Browser-local checkpoints demonstrate the intended experience. Secure durable execution, tool authorization and approval enforcement must be implemented on the server.')}
function studioCandidateResult(s){const c=studio.constraints,reasons=[];if(!s.feasible)reasons.push('Fails authored feasibility fixture');if(s.delay>c.delay)reasons.push('Delay exceeds '+c.delay+' min');if(s.connections>c.connections)reasons.push('Connection exposure exceeds '+c.connections);if(s.cost>c.cost)reasons.push('Relative cost exceeds '+c.cost);return {scenario:s,eligible:!reasons.length,reasons}}
function studioOptimizerView(){const c=studio.constraints,results=scenarios.map(studioCandidateResult),eligible=results.filter(r=>r.eligible).sort((a,b)=>a.scenario[c.objective]-b.scenario[c.objective]);return studioHead('Recovery constraints & candidate review','Compare the same three hand-authored candidates against explicit bounds. This is a local constraint check, not a connected optimization solver.')+`<div class="studio-layout"><section class="card"><h3>Scenario input version ${studio.constraintVersion}</h3><form id="studioConstraintForm"><div class="studio-form-grid">${[['delay','Maximum total delay (minutes)',c.delay],['connections','Maximum at-risk connections',c.connections],['cost','Maximum relative cost units',c.cost]].map(([n,l,v])=>`<div><label class="field" for="constraint-${n}">${l}</label><input id="constraint-${n}" class="control" name="${n}" type="number" min="0" max="100000" step="1" value="${v}" required></div>`).join('')}<div><label class="field" for="constraint-objective">Minimize</label><select class="control" id="constraint-objective" name="objective">${[['connections','At-risk connections'],['delay','Total delay'],['cost','Relative cost']].map(([v,l])=>`<option value="${v}" ${c.objective===v?'selected':''}>${l}</option>`).join('')}</select></div></div><div class="studio-dialog-foot"><button class="btn primary">Apply constraints & compare</button></div></form><p class="footnote">Changing inputs invalidates pending local approvals bound to the previous version.</p></section><section class="card"><h3>Comparison outcome</h3><div class="studio-stat"><span>Eligible authored candidates</span><strong>${eligible.length} / ${scenarios.length}</strong><small>Local bounds + fixture feasibility flag</small></div><p>${eligible.length?'Lowest selected objective: <strong>Candidate '+eligible[0].scenario.id+'</strong>.':'No authored candidate meets these bounds. Relax an assumption or request a new solver proposal in the future backend.'}</p><p class="small">A genuine solver must model aircraft, rotations, crew and airport constraints. The fixture feasibility flag is not independent operational verification.</p></section></div>`+studioSection('Candidate comparison','Values are the original authored examples, never model or solver outputs.')+studioTable(['Candidate','Delay / connections / cost','Constraint result','Review'],results.map(r=>[escapeHtml(r.scenario.id+' · '+r.scenario.name),r.scenario.delay+' min / '+r.scenario.connections+' connections / '+r.scenario.cost+' units',r.eligible?pill('Eligible in local exercise'):pill('Blocked')+'<small>'+escapeHtml(r.reasons.join('; '))+'</small>',studioButton('Request versioned review','proposal:'+r.scenario.id,false,!r.eligible)]))+studioBoundary('Approval requests retain the exact local input version and candidate. No schedule, aircraft allocation or passenger itinerary is changed by this interface.')}
function studioSecurityView(){return studioHead('Security & governance control room','Design authentication, authorization, privacy and audit controls, then attach real verification evidence during implementation.')+`<div class="studio-actions"><button class="btn primary" data-page="Identity & access">Access-flow preview</button><button class="btn" data-page="Roles & permissions">Permission matrix</button>${studioButton('Preview authorization decision','permissionPreview')}${studioButton('Attach security evidence','evidence:security-0')}</div>`+studioStats([['Connected identity providers',0,'Authentication not implemented'],['Verified security tests',0,'No server test evidence supplied'],['Proposed role types',3,'Local policy design'],['Operational authority','None','Independent portfolio UI']])+`<div class="studio-layout"><section class="card"><h3>Required controls & evidence</h3>${STUDIO_AREAS.find(a=>a.id==='security').requirements.map((r,i)=>studioEvidenceRow('security-'+i,r)).join('')}</section><section class="card"><h3>Threat review</h3><ul class="studio-list">${[['Cross-resource access','Enforce resource, tenant and purpose scope on the server.'],['Retrieved prompt injection','Treat document instructions as untrusted content.'],['Unbound approval','Require proposal version, expiry and current reviewer authorization.'],['Sensitive data exposure','Minimize data, protect secrets and enforce retention.'],['Audit tampering','Use protected server-side event records and correlation IDs.']].map(([t,d])=>`<li><span class="check-symbol">!</span><span><strong>${t}</strong><small>${d}</small></span></li>`).join('')}</ul></section></div>`+studioRowsFallback()}
const STUDIO_PERMISSION_ACTIONS=['Read evidence','Propose recovery','Record approval','Manage release'];
const STUDIO_PERMISSION_ROLES=['Analyst','Reviewer','Platform operator'];
function studioPermission(roleName,actionIndex){const key=roleName+'|'+actionIndex;return Object.hasOwn(studio.permissions,key)?studio.permissions[key]:actionIndex===0||(roleName==='Analyst'&&actionIndex===1)||(roleName==='Reviewer'&&actionIndex===2)||(roleName==='Platform operator'&&actionIndex===3)}
function studioPermissionsView(){return studioHead('Proposed permission matrix','Edit an intended role policy and inspect a local policy decision. These settings grant no actual access.')+`<div class="studio-actions">${studioButton('Preview authorization decision','permissionPreview',true)}<button class="btn" data-page="Identity & access">Identity experience</button></div><form id="studioPermissionForm"><div class="table-wrap"><table class="studio-matrix"><thead><tr><th scope="col">Proposed role</th>${STUDIO_PERMISSION_ACTIONS.map(a=>'<th scope="col">'+a+'</th>').join('')}</tr></thead><tbody>${STUDIO_PERMISSION_ROLES.map(r=>`<tr><th scope="row">${r}</th>${STUDIO_PERMISSION_ACTIONS.map((a,i)=>`<td><input type="checkbox" name="${r}|${i}" aria-label="${r}: ${a}" ${studioPermission(r,i)?'checked':''}></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="studio-dialog-foot"><button class="btn primary">Save proposed policy locally</button></div></form>${studioBoundary('Checkboxes update a browser-local policy sketch. Production authorization must be enforced independently on every service request, with tested denial behavior.')}${studioRowsFallback()}`}
function studioApiView(){return studioHead('API contracts & request sandbox','Design typed service boundaries, request validation and explicit denial states without sending network requests.')+`<div class="studio-actions">${studioButton('Draft API contract','new:api',true)}<button class="btn" data-page="Identity & access">Authorization boundary</button><button class="btn" data-page="Cloud infrastructure">Deployment design</button></div><div class="studio-layout"><section class="card"><h3>Local request preview</h3><form id="studioApiForm"><label class="field" for="studioApiPrincipal">Preview principal</label><select id="studioApiPrincipal" name="principal" class="control"><option value="analyst">Synthetic analyst · scoped read</option><option value="denied">Synthetic denied principal</option></select><label class="field" for="studioApiBody">Request JSON</label><textarea id="studioApiBody" name="body" class="control" required maxlength="6000">{"flight_id":"AIN-412","snapshot_id":"SYNTHETIC-01"}</textarea><div class="studio-dialog-foot"><button class="btn primary">Validate local request</button></div></form></section><section class="card"><h3>Preview response</h3><div id="studioApiResponse" aria-live="polite">${studio.apiResult?'<pre>'+escapeHtml(JSON.stringify(studio.apiResult,null,2))+'</pre>':'<div class="studio-empty">Validate a request to preview schema errors or an access-denied response.</div>'}</div><p class="footnote">This is a local schema/response demonstration. It does not authenticate a principal or call an API.</p></section></div>`+studioSection('Proposed service contracts')+studioTable(['Contract / path','Method / scope','Write protection'],studio.apiContracts.map(a=>[escapeHtml(a.name)+'<small>'+escapeHtml(a.path)+'</small>',escapeHtml(a.method)+'<small>'+escapeHtml(a.authorization)+'</small>',escapeHtml(a.idempotency)]))+studioRowsFallback()}
function studioReleaseView(){const localAccepted=STUDIO_GATES.filter((g,i)=>studio.evidence['gate-'+i]?.status==='Accepted in local exercise').length;return studioHead('Release qualification & evidence','Trace the agreed scope to evidence, review unresolved gates and rehearse a controlled rollout. Production release remains unqualified.')+`<div class="studio-actions">${studioButton('Create release candidate','new:release',true)}${studioButton('Rehearse rollout','start:deployment')}${studioButton('Complete platform scope','scope')}${studioButton('Export implementation handoff','exportScope')}</div>`+studioStats([['Qualification gates',STUDIO_GATES.length,'Evidence required for each'],['Locally accepted',localAccepted,'Exercise decisions, not certification'],['Connected environments',0,'No cloud deployment configured'],['Production qualification','Pending','No real release evidence']])+`<section class="card"><h3>Release gates</h3>${STUDIO_GATES.map(([name,desc],i)=>studioEvidenceRow('gate-'+i,name+' · '+desc)).join('')}</section>`+studioSection('Release candidates')+studioTable(['Candidate / environment','Revision / rollback','Owner / status'],studio.releases.map(r=>[escapeHtml(r.name)+'<small>'+escapeHtml(r.environment)+'</small>',escapeHtml(r.revision)+'<small>'+escapeHtml(r.rollback)+'</small>',escapeHtml(r.owner)+'<small>Local proposal; not deployed</small>']))+studioSection('Rollout rehearsals')+studioRunList(['deployment'])+studioBoundary('Even when every local gate is marked accepted, this prototype cannot establish production readiness. Verified deployment, security, monitoring, rollback and recovery evidence is required.')}
function studioCloudView(){return studioHead('Environments & deployment topology','Prepare a reproducible primary deployment before adding other cloud profiles.')+`<div class="studio-actions">${studioButton('Draft release candidate','new:release',true)}${studioButton('Rehearse rollout','start:deployment')}<button class="btn" data-page="Disaster recovery">Recovery plan</button></div><div class="studio-grid">${[['Application tier','Authenticated UI, API gateway and typed operational services.'],['Data tier','Persistent workflow database, licensed raw assets, feature tables and evidence index.'],['Worker tier','Ingestion, model jobs, retrieval processing and bounded agent workflows.'],['Control tier','Secrets, resource permissions, audit records and approval validation.'],['Delivery tier','Versioned infrastructure, build gates, safe rollout and migration checks.'],['Reliability tier','Health checks, service objectives, alerts, backups and tested restore.']].map(([t,d])=>`<section class="studio-card"><div class="eyebrow">Not provisioned</div><h3>${t}</h3><p>${d}</p></section>`).join('')}</div>${studioSection('Environment readiness')}${studioTable(['Environment','Identity / storage / services','Status'],['Development','Test','Staging','Production'].map(e=>[e,'No deployed resources connected',pill('Not configured')]))}${studioRowsFallback()}`}
function studioObservabilityView(){const failed=studio.runs.filter(r=>r.status==='Failed').length,waiting=studio.runs.filter(r=>['Queued','Paused','Awaiting human review'].includes(r.status)).length;return studioHead('Monitoring, signals & response','Define service objectives and response ownership. The counters below describe local UI runs only.')+`<div class="studio-actions">${studioButton('Define monitor','new:monitor',true)}<button class="btn" data-page="Alert center">Alert triage</button><button class="btn" data-page="Disaster recovery">Recovery drills</button></div>`+studioStats([['Local run records',studio.runs.length,'Browser-local rehearsal activity'],['Failed rehearsals',failed,'Injected UI failures'],['Waiting or paused',waiting,'Local checkpoint state'],['Live service metrics','Unavailable','No telemetry connection']])+studioTable(['Monitor / signal','Threshold / owner','Response'],studio.monitors.map(m=>[escapeHtml(m.name)+'<small>'+escapeHtml(m.signal)+'</small>',escapeHtml(m.threshold)+'<small>'+escapeHtml(m.owner)+'</small>',escapeHtml(m.response)]))+studioSection('Required telemetry','No latency, uptime, model-drift or cost measurements are fabricated.')+`<div class="studio-grid">${[['API health','Latency distributions, error rates, saturation and trace correlation.'],['Data freshness','Source age, quarantine volume, duplicate rate and backlog age.'],['AI behavior & cost','Grounding, abstention, tool failures, drift and actual provider usage.']].map(([t,d])=>`<section class="studio-card"><span class="pill">Not measured</span><h3>${t}</h3><p>${d}</p></section>`).join('')}</div>`+studioRowsFallback()}
function studioRecoveryView(){return studioHead('Backup, restore & interruption recovery','Define recovery targets, rehearse the operator experience and reserve measured results for actual drills.')+`<div class="studio-actions">${studioButton('Plan recovery drill','new:drill',true)}${studioButton('Rehearse restoration','start:drill')}<button class="btn" data-page="Release management">Recovery release gate</button></div>`+studioTable(['Runbook / resource','Proposed targets','Owner / actual result','Action'],studio.drills.map(d=>[escapeHtml(d.name)+'<small>'+escapeHtml(d.resource)+'</small>','RTO '+escapeHtml(d.rto)+' min / RPO '+escapeHtml(d.rpo)+' min',escapeHtml(d.owner)+'<small>Actual recovery time and data loss: not measured</small>',studioButton('Rehearse drill','start:drill:'+d.id)]))+`<div class="studio-layout" style="margin-top:22px"><section class="card"><h3>Restore acceptance</h3><ul class="studio-list">${['Use an isolated restoration environment','Verify backup integrity and version compatibility','Reconcile record counts, identifiers and evidence lineage','Verify access controls after restoration','Measure actual recovery time and recoverable data loss','Record defects, corrective actions and a repeat drill'].map(x=>`<li><span class="check-symbol">•</span><span>${x}</span></li>`).join('')}</ul></section><section class="card"><h3>Execution boundary</h3><p>No backups or infrastructure are connected. A local rehearsal does not restore a database, prove an RTO/RPO or recover an agent runtime.</p>${studioButton('Attach recovery evidence','evidence:resilience-5')}</section></div>`+studioSection('Recovery rehearsals')+studioRunList(['drill'])+studioRowsFallback()}
function studioQualityView(){return studioHead('Data quality & quarantine','Run bounded checks on the six local flight fixtures, or validate a small pasted JSON preview.')+`<div class="studio-actions">${studioButton('Check local flight fixtures','quality',true)}${studioButton('Validate JSON preview','json')}<button class="btn" data-page="Ingestion pipelines">Pipeline handling</button></div>${studio.qualityResult?studioTable(['Check','Local result','Detail'],studio.qualityResult.map(r=>[escapeHtml(r.name),pill(r.pass?'Passed on fixtures':'Failed on fixtures'),escapeHtml(r.detail)])):'<div class="studio-empty">Run local checks to inspect duplicate identifiers, required fields and numeric delay values.</div>'}${studioBoundary('These checks cover the browser fixtures only. They do not validate a historical or live aviation dataset.')}${studioRowsFallback()}`}
function studioLineageView(){const nodes=[['Source release','Pinned license, checksum and original snapshot','Dataset registry'],['Normalized records','Business keys, units and available-at timestamps','Lakehouse explorer'],['Features & evidence','Decision cutoff, model version and source spans','Prediction models'],['Decision & audit','Proposal input version, rationale and outcome','Audit trail']],selected=nodes[studio.lineageNode]||nodes[0];return studioHead('Lineage & decision provenance','Inspect the planned links from authorized sources to derived features, evidence and human decisions.')+`<div class="studio-lineage">${nodes.map(([t,d],i)=>`<button class="${studio.lineageNode===i?'active':''}" data-action="studio:lineage:${i}" aria-pressed="${studio.lineageNode===i}"><strong>${t}</strong><small>${d}</small></button>`).join('')}</div><section class="card"><h3>${selected[0]}</h3><p>${selected[1]}</p><p class="muted">Lineage edges are a design preview. No provenance service or immutable source manifest is connected.</p><button class="btn primary" data-page="${selected[2]}">Open related workspace</button></section>${studioRowsFallback()}`}
function studioAcceptanceView(){return studioHead('Quality, evaluation & user acceptance','Define test cases, capture evidence and distinguish local fixture checks from unrun production evaluations.')+`<div class="studio-actions">${studioButton('Define test case','new:test',true)}${studioButton('Run local fixture checks','checks')}${studioButton('Rehearse test lifecycle','start:test')}${studioButton('Export acceptance scope','exportScope')}</div>`+studioStats([['Acceptance requirements',studioCounts().requirements,'Mapped to twelve platform areas'],['Local test designs',studio.tests.length,'Not executed against a backend'],['Actual model/agent evaluations',0,'No provider runtime connected'],['Verified production suites',0,'Implementation phase required']])+studioTable(['Test / suite','Setup / expected behavior','Owner / result'],studio.tests.map(t=>[escapeHtml(t.name)+'<small>'+escapeHtml(t.suite)+'</small>',escapeHtml(t.setup)+'<small>'+escapeHtml(t.expected)+'</small>',escapeHtml(t.owner)+'<small>Not run against production services</small>']))+(studio.checkResult?studioSection('Executed local fixture checks')+studioTable(['Assertion','Result','Scope'],studio.checkResult.map(r=>[escapeHtml(r.name),pill(r.pass?'Passed':'Failed'),'Browser fixture logic only'])):'')+studioSection('Test lifecycle rehearsals')+studioRunList(['test'])+studioSection('Requirement traceability','Every requirement needs implementation evidence and a named reviewer.')+studioAreaCards()}
function studioApiResponse(body,principal){let payload;try{payload=JSON.parse(body)}catch{return {mode:'local_schema_preview',status:400,error:'Request body is not valid JSON'}}if(!payload||typeof payload!=='object'||Array.isArray(payload))return {mode:'local_schema_preview',status:400,error:'Request must be a JSON object'};if(principal==='denied')return {mode:'local_policy_preview',status:403,error:'Access denied by the selected preview scenario',server_authorization:false};if(typeof payload.flight_id!=='string'||!payload.flight_id.trim()||typeof payload.snapshot_id!=='string'||!payload.snapshot_id.trim())return {mode:'local_schema_preview',status:400,error:'Nonempty string flight_id and snapshot_id are required'};const f=state.flights.find(x=>x.id===payload.flight_id);return f?{mode:'synthetic_ui_response',status:200,snapshot_id:payload.snapshot_id,record:f,provenance:'Written flight fixture; not a network response'}:{mode:'local_schema_preview',status:404,error:'No flight fixture matches this identifier'}}
function studioJsonModal(){modal('Validate a JSON data preview',`<p class="studio-form-note">Paste a JSON array of synthetic records. Preview is limited to 5,000 rows and 1 MB; large datasets belong in a backend pipeline.</p><form id="studioJsonForm"><label class="field" for="studioJson">Record array</label><textarea class="control" id="studioJson" name="json" required maxlength="1000000">${escapeHtml(JSON.stringify(state.flights.slice(0,2),null,2))}</textarea><div class="studio-dialog-foot"><button class="btn primary">Validate preview</button></div></form><div id="studioJsonResult" class="studio-evaluation-result" aria-live="polite"></div>`)}
function studioJsonValidate(text){let rows;try{rows=JSON.parse(text)}catch{return {valid:false,error:'Invalid JSON. Correct the syntax and try again.'}}if(!Array.isArray(rows)||!rows.length)return {valid:false,error:'Use a nonempty JSON array of record objects.'};if(rows.length>5000)return {valid:false,error:'Preview limit is 5,000 rows. Use a server pipeline for larger data.'};if(rows.some(r=>!r||typeof r!=='object'||Array.isArray(r)))return {valid:false,error:'Every row must be an object.'};const fields=Object.keys(rows[0]),schemaMismatches=rows.filter(r=>Object.keys(r).sort().join('|')!==[...fields].sort().join('|')).length;const ids=rows.filter(r=>r.id!==undefined).map(r=>String(r.id)),duplicates=ids.length-new Set(ids).size;return {valid:schemaMismatches===0&&duplicates===0,rows:rows.length,fields:fields.length,schema_mismatch_rows:schemaMismatches,duplicate_ids:duplicates,source:'Pasted preview only; no data uploaded or ingested'}}
function studioFixtureQuality(){const flights=state.flights,ids=flights.map(f=>f.id);return [{name:'Unique flight identifiers',pass:new Set(ids).size===ids.length,detail:ids.length+' fixture records checked'},{name:'Required flight fields',pass:flights.every(f=>f.id&&f.route&&f.aircraft),detail:'ID, route and aircraft must be nonempty'},{name:'Nonnegative finite delay',pass:flights.every(f=>Number.isFinite(Number(f.delay))&&Number(f.delay)>=0),detail:'Delay values checked as minutes'}]}
function studioFixtureChecks(){return [...studioFixtureQuality(),{name:'Infeasible candidate cannot pass eligibility',pass:!studioCandidateResult(scenarios.find(s=>s.id==='C')).eligible,detail:'Candidate C retains its authored infeasible flag'},{name:'Fixture evidence is identifiable',pass:DOCS.length===3&&DOCS.every(d=>d.id&&d.text),detail:'Three written source fixtures'}]}
function studioEvidenceModal(key){const e=studio.evidence[key]||{};modal('Acceptance evidence · local review',`<p class="studio-form-note">Capture a reference and a reviewer disposition. This record is not independent verification of a production control.</p><form id="studioEvidenceForm" data-key="${escapeHtml(key)}"><label class="field" for="evidenceOwner">Owner / reviewer</label><input class="control" id="evidenceOwner" name="owner" value="${escapeHtml(e.owner||'Engineering review')}" required maxlength="200"><label class="field" for="evidenceReference">Evidence reference</label><input class="control" id="evidenceReference" name="reference" value="${escapeHtml(e.reference||'')}" required maxlength="700" placeholder="Report identifier, artifact path or reviewed test reference"><label class="field" for="evidenceNotes">Review notes and limitations</label><textarea class="control" id="evidenceNotes" name="notes" required maxlength="3000">${escapeHtml(e.notes||'')}</textarea><label class="field" for="evidenceDisposition">Local disposition</label><select id="evidenceDisposition" name="status" class="control">${['Evidence submitted','Needs revision','Accepted in local exercise'].map(s=>`<option ${e.status===s?'selected':''}>${s}</option>`).join('')}</select><div class="studio-dialog-foot"><button class="btn primary">Save local review</button><button class="btn" type="button" data-action="close">Cancel</button></div></form>`)}
function studioPermissionPreview(){modal('Local authorization preview',`<p class="studio-form-note">Test the proposed matrix only. No authenticated identity or real permission is involved.</p><form id="studioPermissionPreview"><label class="field" for="previewPolicyRole">Proposed role</label><select class="control" id="previewPolicyRole" name="role">${STUDIO_PERMISSION_ROLES.map(r=>'<option>'+r+'</option>').join('')}</select><label class="field" for="previewPolicyAction">Requested action</label><select class="control" id="previewPolicyAction" name="action">${STUDIO_PERMISSION_ACTIONS.map((a,i)=>`<option value="${i}">${a}</option>`).join('')}</select><div class="studio-dialog-foot"><button class="btn primary">Preview policy decision</button></div></form><div id="studioPermissionResult" class="studio-evaluation-result" aria-live="polite"></div>`)}
function studioGenerativeView(){return studioHead('Grounded answers & source review','Prepare questions, summaries and comparisons with visible source references and an explicit insufficient-evidence state.')+`<div class="studio-layout"><section class="card"><h3>Grounded response workbench</h3><form id="studioAnswerForm"><label class="field" for="studioAnswerTask">Task</label><select class="control" name="task" id="studioAnswerTask"><option value="question">Answer a question</option><option value="summary">Review source excerpts for a summary</option><option value="compare">Compare source metadata</option></select><label class="field" for="studioAnswerMode">Execution mode</label><select class="control" name="mode" id="studioAnswerMode"><option value="extract">Local extractive preview · no LLM</option><option value="llm">Generative provider · not connected</option></select><label class="field" for="studioAnswerQuestion">Question / investigation purpose</label><textarea class="control" id="studioAnswerQuestion" name="question" required maxlength="2000">What evidence and review are required before a recovery proposal?</textarea><div class="studio-dialog-foot"><button class="btn primary">Prepare grounded response</button></div></form><p class="footnote">Local mode returns exact fixture excerpts or metadata, not an AI-generated answer. Registered document drafts are not added to this retrieval corpus.</p></section><section class="card"><h3>Response & citations</h3><div id="studioAnswerResult" aria-live="polite"><div class="studio-empty">Choose a task and inspect the evidence supporting the response.</div></div></section></div>`+studioSection('Eligible fixture sources')+studioTable(['Source','Class / version','Inspection'],DOCS.map(d=>[escapeHtml(d.id+' · '+d.title),escapeHtml(d.kind)+'<small>'+escapeHtml(d.date)+' · Written fixture v1</small>',studioButton('Inspect source','doc:'+d.id)]))+studioBoundary('Production RAG needs permission-aware retrieval, embeddings, a connected provider, grounded-answer evaluation and monitored failure handling. These are not supplied by the local preview.')}
function studioPolicyView(){return studioHead('Prompts, tools & execution boundaries','Version prompt drafts, allowlisted tools, execution budgets and required human checkpoints.')+`<div class="studio-actions">${studioButton('Draft policy','new:policy',true)}<button class="btn" data-page="AI agent command">Agent investigation</button><button class="btn" data-page="AI evaluation lab">Adversarial evaluation plan</button></div>`+studioTable(['Policy / version','Instruction draft','Tools / limits'],studio.policies.map(p=>[escapeHtml(p.name)+'<small>Version '+escapeHtml(p.version)+'</small>',escapeHtml(p.prompt),escapeHtml(p.tools)+'<small>'+escapeHtml(p.limit)+' calls · '+escapeHtml(p.approval)+'</small>']))+studioBoundary('A written policy is not an enforced control. The future tool gateway must independently validate scope, schema, deadlines, budgets and approval requirements.')+studioRowsFallback()}
function studioLakehouseView(){return studioHead('Storage contracts & persistence','Inspect the proposed raw-to-curated layers and the data guarantees needed by features, retrieval and operational workflows.')+`<div class="studio-grid">${[['Bronze / source assets','Immutable source release, checksum, ingest time and rights reference.'],['Silver / normalized records','Stable business keys, units, deduplication and source-availability timestamps.'],['Gold / decision inputs','Time-safe features, defined denominators and versioned metric snapshots.']].map(([t,d])=>`<section class="studio-card"><div class="eyebrow">Storage not connected</div><h3>${t}</h3><p>${d}</p><button class="btn" data-page="Lineage explorer">Inspect lineage</button></section>`).join('')}</div>${studioRowsFallback()}`}
function studioApprovalBindingValid(id){const b=studio.bindings[id];return !b||(b.version===studio.constraintVersion&&b.inputs===JSON.stringify(studio.constraints)&&Date.now()<b.expires)}
function studioRequestProposal(id){const s=scenarios.find(x=>x.id===id);if(!s||!studioCandidateResult(s).eligible){notify('This candidate does not meet the current local bounds');return}const duplicate=state.approvals.find(a=>a.status==='Pending'&&studio.bindings[a.id]?.version===studio.constraintVersion&&studio.bindings[a.id]?.candidate===id);if(duplicate){go('Human approvals');notify('This exact local proposal already has a pending review');return}const requestId=studioId('APR-UI');studio.bindings[requestId]={candidate:id,version:studio.constraintVersion,inputs:JSON.stringify(studio.constraints),snapshot:structuredClone(s),created:studioNow(),expires:Date.now()+30*60*1000};state.approvals.unshift({id:requestId,title:'Recovery '+id+' · input version '+studio.constraintVersion,status:'Pending',owner:role,rationale:''});studioSave();audit('ui.proposal.review.requested',requestId+' · exact local input version '+studio.constraintVersion);go('Human approvals');notify('Versioned local review requested · no operational execution')}
const studioSpecialBase=fullSpecialView;
fullSpecialView=function(name){const views={'Ingestion pipelines':studioPipelineView,'Dataset registry':studioDatasetView,'Streaming events':studioStreamingView,'Prediction models':studioModelView,'Model evaluation':studioEvaluationView,'Document intelligence':studioDocumentsView,'Evidence & RAG':studioGenerativeView,'AI agent command':studioAgentsView,'Prompt & tool policies':studioPolicyView,'Recovery optimizer':studioOptimizerView,'Scenario comparison':studioOptimizerView,'Security center':studioSecurityView,'Roles & permissions':studioPermissionsView,'API gateway':studioApiView,'Release management':studioReleaseView,'Cloud infrastructure':studioCloudView,'Observability':studioObservabilityView,'Disaster recovery':studioRecoveryView,'Data quality':studioQualityView,'Lineage explorer':studioLineageView,'Lakehouse explorer':studioLakehouseView,'AI evaluation lab':studioAcceptanceView};return views[name]?views[name]():studioSpecialBase(name)};
const studioOverviewBase=overview;
overview=function(){return studioOverviewBase()+studioSection('Build & operate the full platform','Twelve connected implementation areas, with acceptance evidence and local workflow rehearsals.',studioButton('View complete scope','scope'))+studioAreaCards()+studioBoundary('All 64 aviation workspaces are preserved. The connected research panel shows local database and model evidence; production services and qualification remain incomplete.')};
const studioRenderBase=render;
render=function(){studioRenderBase();const tabs=document.querySelector('.workspace-tabs');tabs.insertAdjacentHTML('beforeend',`<button role="tab" aria-selected="${fullTab==='acceptance'}" class="workspace-tab ${fullTab==='acceptance'?'active':''}" data-action="studio:acceptance">Acceptance</button>`);if(fullTab==='acceptance'){tabs.querySelectorAll('[data-action^="full:tab:"]').forEach(t=>{t.setAttribute('aria-selected','false');t.classList.remove('active')});const panel=document.querySelector('[role="tabpanel"]');panel.setAttribute('aria-label','Acceptance requirements');panel.innerHTML=studioReadinessView()}const tools=document.querySelector('.premium-tools');tools.insertAdjacentHTML('beforeend',studioButton('Platform scope','scope'));if(!$('studioScopeButton')){$('theme').insertAdjacentHTML('beforebegin','<button class="btn sm" id="studioScopeButton" data-action="studio:scope">Platform scope</button>')}document.querySelectorAll('.studio-actions button').forEach(b=>{b.type='button'});syncNavigationInert()};
const studioReportBase=reportPayload;
reportPayload=function(){return {...studioReportBase(),implementation_area:studioRouteArea(page),local_delivery_state:structuredClone(studio),operational_execution:false}};
const studioActBase=act;
act=function(action){if(!action.startsWith('studio:')){studioActBase(action);if(action.startsWith('approval:')){const id=action.slice(9),binding=studio.bindings[id];if(binding&&document.querySelector('.dialog-box')){const valid=studioApprovalBindingValid(id);document.querySelector('.dialog-head').insertAdjacentHTML('afterend',`<div class="studio-inline-warning"><strong>Bound to candidate ${escapeHtml(binding.candidate)}, input version ${binding.version}.</strong><br>Local expiry: ${new Date(binding.expires).toISOString()}<br>${valid?'Current local input version. This is a simulated human decision.':'Stale or expired proposal. A new request is required.'}</div><pre>${escapeHtml(binding.inputs)}</pre>`);if(!valid)document.querySelectorAll('#approvalForm button[type="submit"]').forEach(b=>b.disabled=true)}}return}const [,key,arg,rest]=action.split(':');if(key==='scope'){studioScope();return}if(key==='acceptance'){fullTab='acceptance';render();return}if(key==='new'){studioForm(arg);return}if(key==='start'){const collections={pipeline:'pipelines',training:'models',document:'documents',deployment:'releases',drill:'drills'};const row=studio[collections[arg]]?.find(r=>r.id===rest);studioStartRun(arg,row?.name||row?.title||'');return}if(key==='run'){studioRunDetail(arg);return}if(['runStart','runNext','runPause','runResume','runFail','runRetry','runCancel'].includes(key)){studioRunTransition(key,arg);return}if(key==='runExport'){const run=studio.runs.find(r=>r.id===arg);if(run)premiumDownload('AIN_local_rehearsal_'+arg+'.json',{mode:'ui_rehearsal_only',run,actual_execution:false});return}if(key==='model'){studioModelDetail(arg);return}if(key==='json'){studioJsonModal();return}if(key==='quality'){studio.qualityResult=studioFixtureQuality();studioSave();render();notify('Local flight fixture checks completed');return}if(key==='checks'){studio.checkResult=studioFixtureChecks();studioSave();render();notify('Local fixture assertions executed; production suites remain unrun');return}if(key==='evidence'){studioEvidenceModal(arg);return}if(key==='proposal'){studioRequestProposal(arg);return}if(key==='permissionPreview'){studioPermissionPreview();return}if(key==='lineage'){studio.lineageNode=Number(arg);studioSave();render();return}if(key==='agentNode'){const content=[['Snapshot tools','query_flight_kpis','Bounded aggregate or fixture record; no airline write access.'],['Evidence tools','retrieve_evidence','Authorized source identifiers, exact spans and source versions.'],['Proposal tools','propose_scenario','A proposal and independent verifier result are required.'],['Governance checkpoint','evaluate_policy','A current authenticated human must dispose of the exact proposal.']][Number(arg)];modal(content[0],`<h3>${content[1]}</h3><p>${content[2]}</p>${studioBoundary('Tool contract preview only; no actual tool executor is connected.')}`);return}if(key==='doc'){const d=DOCS.find(x=>x.id===arg)||studio.documents.find(x=>x.id===arg);if(d)modal('Source inspection · '+d.title,`<dl class="record-detail"><div><dt>Identifier</dt><dd>${escapeHtml(d.id)}</dd></div><div><dt>Class</dt><dd>${escapeHtml(d.kind)}</dd></div><div><dt>Date / version</dt><dd>${escapeHtml(d.date||d.created)} · ${escapeHtml(d.version||'Fixture v1')}</dd></div><div><dt>Rights</dt><dd>${escapeHtml(d.rights||'Written synthetic fixture')}</dd></div></dl><section class="source-card"><h4>Exact local source text</h4><p>${escapeHtml(d.text)}</p></section>${studioButton('Rehearse processing','start:document:'+arg)}`);return}if(key==='exportScope'){premiumDownload('AIN_implementation_and_acceptance_scope.json',{title:'AIN end-to-end implementation handoff',scope:'UI preparation; real services not implemented',workspace_count:64,areas:STUDIO_AREAS,workspace_mapping:navNames.map(n=>({workspace:n,area:studioRouteArea(n).id,owner:reg(n).owner,proposed_endpoint:reg(n).endpoint})),release_gates:STUDIO_GATES,local_evidence:studio.evidence,backend_services_connected:0});notify('Implementation scope exported');return}};
document.addEventListener('submit',e=>{if(e.target.id==='approvalForm'&&!studioApprovalBindingValid(e.target.dataset.id)){e.preventDefault();e.stopImmediatePropagation();notify('Approval blocked: proposal inputs changed or local review expired. Request a new review.')}},true);
document.addEventListener('submit',e=>{const id=e.target.id;if(!id.startsWith('studio'))return;e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(id==='studioCreateForm'){const type=e.target.getAttribute('data-type'),cfg=STUDIO_FORMS[type];for(const [name]of cfg.fields){if(typeof data[name]==='string')data[name]=data[name].trim();if(!data[name]){notify('Complete all required fields');return}}if(type==='api'){try{const schema=JSON.parse(data.schema);if(!schema||typeof schema!=='object'||Array.isArray(schema))throw Error()}catch{notify('Example request must be a valid JSON object');return}}const record={...data,id:studioId(type.toUpperCase()),created:studioNow(),status:'Local draft'};studio[cfg.collection].unshift(record);studioSave();audit('ui.design.created',type+' · '+record.id);close();render();notify('Local '+type+' draft saved; no service executed');return}if(id==='studioRunForm'){const kind=e.target.dataset.kind;if(!STUDIO_STAGES[kind])return;if(!data.name.trim()||!data.reference.trim()){notify('Enter a run name and source reference');return}const run={id:studioId('RUN'),kind,name:data.name.trim(),reference:data.reference.trim(),failure:data.failure,status:'Queued',step:0,attempt:1,created:studioNow(),log:[studioNow()+' Local UI rehearsal queued; no server execution']};studio.runs.unshift(run);studioSave();close();render();studioRunDetail(run.id);return}if(id==='studioConstraintForm'){const next={delay:Number(data.delay),connections:Number(data.connections),cost:Number(data.cost),objective:data.objective};if(!['delay','connections','cost'].includes(next.objective)||[next.delay,next.connections,next.cost].some(v=>!Number.isFinite(v)||v<0)){notify('Enter valid nonnegative constraint values');return}if(JSON.stringify(next)!==JSON.stringify(studio.constraints)){studio.constraintVersion++;studio.constraints=next;state.approvals.forEach(a=>{if(a.status==='Pending'&&studio.bindings[a.id])a.status='Needs revision'});audit('ui.proposal.inputs.changed','Constraint version '+studio.constraintVersion+'; pending bound reviews invalidated')}studioSave();render();notify('Local candidate bounds checked');return}if(id==='studioPermissionForm'){STUDIO_PERMISSION_ROLES.forEach(r=>STUDIO_PERMISSION_ACTIONS.forEach((a,i)=>{studio.permissions[r+'|'+i]=Object.hasOwn(data,r+'|'+i)}));studioSave();notify('Proposed matrix saved locally; no actual access changed');return}if(id==='studioPermissionPreview'){const allowed=studioPermission(data.role,Number(data.action));$('studioPermissionResult').innerHTML=`<div class="studio-inline-warning"><strong>${allowed?'Allowed':'Denied'} by the proposed local matrix.</strong><br>No server authorization was evaluated.</div>`;return}if(id==='studioApiForm'){studio.apiResult=studioApiResponse(data.body,data.principal);studioSave();$('studioApiResponse').innerHTML='<pre>'+escapeHtml(JSON.stringify(studio.apiResult,null,2))+'</pre>';return}if(id==='studioJsonForm'){const result=studioJsonValidate(data.json);$('studioJsonResult').innerHTML='<pre>'+escapeHtml(JSON.stringify(result,null,2))+'</pre>';return}if(id==='studioEvidenceForm'){if(!data.owner.trim()||!data.reference.trim()||!data.notes.trim()){notify('Enter an owner, evidence reference and review notes');return}studio.evidence[e.target.dataset.key]={owner:data.owner.trim(),reference:data.reference.trim(),notes:data.notes.trim(),status:data.status,at:studioNow(),verification:'Browser-local review only; not production evidence verification'};studioSave();audit('ui.evidence.reviewed',e.target.dataset.key+' · '+data.status);close();render();notify('Local evidence review saved')}});
const studioResetBase=$('logout').onclick;
$('logout').onclick=()=>{studio=studioSeed();studioSave();studioResetBase()};
// Connect the final agent checkpoint to a real local review record, while retaining no execution authority.
const studioTransitionBase=studioRunTransition;
studioRunTransition=function(key,id){studioTransitionBase(key,id);const run=studio.runs.find(r=>r.id===id);if(run?.status==='Awaiting human review'&&!run.reviewId){const reviewId=studioId('APR-AGENT');run.reviewId=reviewId;state.approvals.unshift({id:reviewId,title:'Agent investigation · '+run.name,status:'Pending',owner:role,rationale:'',agentRunId:run.id});studio.bindings[reviewId]={candidate:'investigation only',version:studio.constraintVersion,inputs:JSON.stringify(studio.constraints),snapshot:{run_id:run.id,reference:run.reference,authority:'No operational write'},created:studioNow(),expires:Date.now()+30*60*1000};run.log.push(studioNow()+' Local human review created: '+reviewId);studioSave();audit('ui.agent.review.requested',reviewId);render();studioRunDetail(id)}};
document.addEventListener('submit',e=>{if(e.target.id==='approvalForm'){const approval=state.approvals.find(a=>a.id===e.target.dataset.id),run=studio.runs.find(r=>r.reviewId===approval?.id);if(run&&['Approved','Rejected'].includes(approval.status)){run.status='Reviewed: '+approval.status+' (UI only)';run.log.push(studioNow()+' Human disposition recorded locally: '+approval.status+'; no action executed');studioSave()}return}if(e.target.id!=='studioAnswerForm')return;e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(f.mode==='llm'){$('studioAnswerResult').innerHTML=studioBoundary('No generative provider is connected. No answer was generated. Use the extractive fixture preview or connect a verified backend in the implementation phase.');return}if(f.task==='compare'){$('studioAnswerResult').innerHTML=DOCS.map(d=>`<section class="source-card"><h4>${escapeHtml(d.id)}</h4><p>${escapeHtml(d.title)}</p><small>${escapeHtml(d.kind)} · ${escapeHtml(d.date)} · Fixture v1</small>${studioButton('Inspect source','doc:'+d.id)}</section>`).join('');return}const words=f.question.toLowerCase().match(/[a-z]{4,}/g)||[],hits=f.task==='summary'?DOCS:DOCS.filter(d=>words.some(w=>(d.title+' '+d.text).toLowerCase().includes(w)));$('studioAnswerResult').innerHTML=hits.length?'<p class="small">Exact fixture excerpts. No generated claims or LLM calls.</p>'+hits.map(d=>`<section class="source-card"><h4>[${escapeHtml(d.id)}] ${escapeHtml(d.title)}</h4><p>${escapeHtml(d.text)}</p>${studioButton('Inspect citation','doc:'+d.id)}</section>`).join(''):studioBoundary('Insufficient fixture evidence. No answer generated.');});
render();




